// Shared (client-safe) types and constants for the AI Mod Builder.

export const MB_VERSIONS = ["1.21.11", "1.21.8", "1.21.4", "1.21.1"] as const;
export type McVersion = (typeof MB_VERSIONS)[number];
export const MB_DEFAULT_VERSION: McVersion = "1.21.11";

export type ModBuildStatus = "queued" | "planning" | "coding" | "compiling" | "repairing" | "scanning" | "succeeded" | "failed";
export const MB_TERMINAL: ModBuildStatus[] = ["succeeded", "failed"];
export const isTerminal = (s: string) => s === "succeeded" || s === "failed";

export type MbEvent = { at: string; stage: string; message: string; detail?: string };
export type MbCommand = { usage: string; description: string; permission: string; whoCanUse: string };
export type MbPermission = { node: string; description: string; default: string };
export type MbConfig = { key: string; description: string; default: string };
export type MbFinding = { severity: "block" | "warn"; rule: string; where: string; message: string; evidence: string };

/** What the portal keeps in ModBuild.result (a trimmed mirror of the service record). */
export type ModBuildResult = {
  summary: { tagline: string; text: string; howToUse: string[]; limitations: string[]; changes: string } | null;
  commands: MbCommand[];
  permissions: MbPermission[];
  config: MbConfig[];
  warnings: string[];
  files: { path: string; size: number }[];
  safety: { verdict: "pass" | "warn" | "block"; findings: MbFinding[] } | null;
  events: MbEvent[];
  repairs: number;
  queuePosition: number;
  errorDetail?: string | null;
};

/** The view the client polls. */
export type ModBuildView = {
  id: string;
  status: ModBuildStatus;
  prompt: string;
  changeRequest: string | null;
  baseBuildId: string | null;
  rootBuildId: string | null;
  mcVersion: string;
  pluginName: string | null;
  version: string | null;
  error: string | null;
  errorCode: string | null;
  attempts: number;
  durationMs: number | null;
  jarName: string | null;
  jarSize: number | null;
  createdAt: string;
  finishedAt: string | null;
  result: ModBuildResult | null;
  lastInstall: { serverId: string; serverName: string; at: string; replaced: string[]; restarted: boolean } | null;
};

/** Customer-facing stage list for the progress timeline. */
export const MB_STAGES: { key: string; label: string; sub: string }[] = [
  { key: "planning", label: "Planning", sub: "Working out what to build" },
  { key: "coding", label: "Writing code", sub: "The AI writes your plugin" },
  { key: "compiling", label: "Compiling", sub: "Turning it into a real plugin file" },
  { key: "repairing", label: "Fixing", sub: "Only if something needs a fix" },
  { key: "scanning", label: "Safety check", sub: "No internet, no system access" },
  { key: "succeeded", label: "Ready", sub: "Download or install it" },
];

export const MB_IDEAS: { label: string; icon: string; prompt: string }[] = [
  { label: "Economy shop", icon: "card", prompt: "A simple economy: players earn coins for killing mobs, can check /balance and /pay each other, and /shop opens a chest menu where they spend coins on diamonds, golden apples and ender pearls. Prices are set in the config." },
  { label: "Join rewards", icon: "sparkles", prompt: "Daily join rewards: the first time a player joins each day they get a reward that grows with their login streak (day 1: 5 bread, day 3: iron, day 7: a diamond). Show a welcome title and their current streak. Streaks are saved." },
  { label: "Custom commands", icon: "terminal", prompt: "Handy player commands: /spawn teleports to the world spawn, /sethome and /home save and return to one home per player, and /discord, /rules and /website print messages I can edit in the config." },
  { label: "Anti-grief zones", icon: "shieldcheck", prompt: "Protected zones: operators mark two corners with /zone pos1 and /zone pos2 and save them with /zone create <name>. Inside a zone, players without permission can't break or place blocks, open chests or explode TNT. Zones survive restarts." },
  { label: "Scoreboard", icon: "barchart", prompt: "A sidebar scoreboard showing the server name, the player's kills, deaths, play time and how many players are online. It updates every few seconds and the title and colours are configurable." },
  { label: "Mini-game", icon: "gamepad", prompt: "A spleef mini-game: operators set the arena and lobby with commands, players /spleef join, a countdown starts when 2 or more are waiting, everyone gets a shovel, and the last player standing wins and is announced to the server." },
  { label: "Chat tools", icon: "chatcode", prompt: "Chat improvements: a configurable chat format with ranks by permission, a word filter that replaces bad words with ***, and /msg and /reply for private messages." },
  { label: "Custom mob drops", icon: "cube", prompt: "Custom mob drops: zombies have a 5% chance to drop an emerald, skeletons drop extra arrows and creepers sometimes drop a TNT block. All chances and items are set in the config." },
];
// Who may use the AI Mod Builder: private preview, feature "modbuilder".
// Both the effective user AND the real signed-in account must be on the
// allowlist, so impersonation can neither open it for someone else nor reveal
// it while the owner is looking at a customer's portal.
import { notFound } from "next/navigation";
import type { User } from "@prisma/client";
import { currentUser, realUser } from "../auth";
import { isPreviewUser } from "../preview-access";

export async function modBuilderUser(): Promise<User | null> {
  const [user, real] = await Promise.all([currentUser(), realUser()]);
  if (!user || !real || user.id !== real.id) return null;
  return (await isPreviewUser(user, "modbuilder")) ? user : null;
}

/** Pages: 404 for everyone outside the preview. */
export async function requireModBuilderUser(): Promise<User> {
  const u = await modBuilderUser();
  if (!u) notFound();
  return u;
}

/** Page metadata that names the feature only for preview users (a 404 must not leak it). */
export async function modBuilderMetadata(title: string) {
  const ok = !!(await modBuilderUser().catch(() => null));
  return { title: ok ? title : "Page not found", robots: { index: false, follow: false } };
}
// Server-only HTTP client for the Mod Builder build service (build VM).
//
// Config, first hit wins:
//   env MODBUILDER_URL / MODBUILDER_API_KEY
//   file $MODBUILDER_ENV_FILE (default /etc/nxeon/modbuilder.env, root:nxeon 0640 so the web user can read it), KEY=VALUE lines
// The URL is the primary-side end of the SSH tunnel
// (nxeon-modbuilder-tunnel.service: 127.0.0.1:7340 -> VM 127.0.0.1:7340).
import { readFileSync } from "node:fs";

type Cfg = { url: string; key: string };
let cached: { cfg: Cfg | null; at: number } | null = null;

export function modBuilderConfig(): Cfg | null {
  if (cached && Date.now() - cached.at < 60_000) return cached.cfg;
  let url = process.env.MODBUILDER_URL || "";
  let key = process.env.MODBUILDER_API_KEY || "";
  if (!url || !key) {
    try {
      const text = readFileSync(process.env.MODBUILDER_ENV_FILE || "/etc/nxeon/modbuilder.env", "utf8");
      for (const line of text.split("\n")) {
        const m = line.match(/^\s*([A-Z_]+)\s*=\s*(.*)\s*$/);
        if (!m) continue;
        if (m[1] === "MODBUILDER_URL" && !url) url = m[2];
        if (m[1] === "MODBUILDER_API_KEY" && !key) key = m[2];
      }
    } catch { /* not configured */ }
  }
  const cfg = url && key ? { url: url.replace(/\/+$/, ""), key } : null;
  cached = { cfg, at: Date.now() };
  return cfg;
}

export class ModBuilderUnavailable extends Error {}

async function call(path: string, init: RequestInit & { timeoutMs?: number } = {}): Promise<Response> {
  const cfg = modBuilderConfig();
  if (!cfg) throw new ModBuilderUnavailable("Mod Builder service is not configured");
  const ctl = new AbortController();
  const t = setTimeout(() => ctl.abort(), init.timeoutMs ?? 15_000);
  try {
    return await fetch(cfg.url + path, {
      ...init,
      cache: "no-store",
      signal: ctl.signal,
      headers: { ...(init.headers || {}), Authorization: `Bearer ${cfg.key}`, ...(init.body ? { "Content-Type": "application/json" } : {}) },
    });
  } catch (e) {
    throw new ModBuilderUnavailable(`Mod Builder service unreachable: ${(e as Error).message}`);
  } finally {
    clearTimeout(t);
  }
}

/** Raw service record (see services/modbuilder/server.js). Only the fields the portal reads. */
export type ServiceBuild = {
  id: string; status: string; error: string | null; errorCode: string | null; errorDetail?: string | null;
  attempts: number; repairs: number; costUsd: number; durationMs: number; pluginName: string | null; version?: string;
  jar: { name: string; size: number; sha256: string } | null;
  summary: { tagline: string; text: string; howToUse: string[]; limitations: string[]; changes: string } | null;
  commands: unknown[]; permissions: unknown[]; config: unknown[]; warnings: string[]; files: { path: string; size: number }[];
  safety: { verdict: "pass" | "warn" | "block"; findings: unknown[] } | null;
  events: { at: string; stage: string; message: string; detail?: string }[];
  queuePosition: number; finishedAt: string | null;
};

export async function svcHealth(): Promise<{ ok: boolean; [k: string]: unknown } | null> {
  try {
    const r = await call("/health", { timeoutMs: 4000 });
    return r.ok ? await r.json() : null;
  } catch { return null; }
}

export async function svcCreate(body: { id: string; prompt: string; mcVersion: string; pluginName?: string; baseBuildId?: string; changeRequest?: string }): Promise<ServiceBuild> {
  const r = await call("/builds", { method: "POST", body: JSON.stringify(body) });
  const j = await r.json().catch(() => ({}));
  if (r.status !== 202) throw new Error((j as { error?: string }).error || `service returned ${r.status}`);
  return j as ServiceBuild;
}

export async function svcGet(id: string): Promise<ServiceBuild | null> {
  const r = await call(`/builds/${encodeURIComponent(id)}`);
  if (r.status === 404) return null;
  if (!r.ok) throw new ModBuilderUnavailable(`service returned ${r.status}`);
  return (await r.json()) as ServiceBuild;
}

export async function svcCancel(id: string): Promise<void> {
  await call(`/builds/${encodeURIComponent(id)}/cancel`, { method: "POST" });
}

export async function svcArtifact(id: string): Promise<Buffer> {
  const r = await call(`/builds/${encodeURIComponent(id)}/artifact`, { timeoutMs: 60_000 });
  if (!r.ok) throw new Error(`artifact fetch failed (${r.status})`);
  return Buffer.from(await r.arrayBuffer());
}

export async function svcSource(id: string, path: string): Promise<Response> {
  return call(`/builds/${encodeURIComponent(id)}/source?path=${encodeURIComponent(path)}`);
}

export async function svcSourceZip(id: string): Promise<Response> {
  return call(`/builds/${encodeURIComponent(id)}/source.zip`, { timeoutMs: 60_000 });
}
// ModBuild persistence: mirror the build service's status into the DB row and
// keep the finished jar on the primary. Used by the API routes (sync on read,
// while someone watches) and by the worker sweep (so a build finishes even if
// nobody keeps the page open). Plain module: safe in the worker.
import { createHash } from "node:crypto";
import { mkdir, writeFile, rename, readFile } from "node:fs/promises";
import { join } from "node:path";
import type { ModBuild, Prisma } from "@prisma/client";
import { db } from "../db";
import { svcArtifact, svcGet, type ServiceBuild } from "./client";
import { isTerminal, type ModBuildResult, type ModBuildView } from "./types";

export const MODBUILD_DIR = process.env.NXEON_MODBUILD_DIR || "/var/lib/nxeon/modbuilds";
export const jarPathFor = (id: string) => join(MODBUILD_DIR, `${id}.jar`);

// A build the service never heard back on for this long is failed (the VM was
// rebuilt, the tunnel down for an hour, ...). Generous: real builds take 1-10 min.
const STALE_MS = 2 * 60 * 60 * 1000;

function toResult(s: ServiceBuild): ModBuildResult {
  return {
    summary: s.summary,
    commands: (s.commands || []) as ModBuildResult["commands"],
    permissions: (s.permissions || []) as ModBuildResult["permissions"],
    config: (s.config || []) as ModBuildResult["config"],
    warnings: s.warnings || [],
    files: s.files || [],
    safety: (s.safety as ModBuildResult["safety"]) || null,
    events: (s.events || []).slice(-150),
    repairs: s.repairs || 0,
    queuePosition: s.queuePosition || 0,
    errorDetail: s.errorDetail ? String(s.errorDetail).slice(0, 6000) : null,
  };
}

/** Pull the service's view of one build into its row. Never throws for an unreachable service. */
export async function syncBuild(row: ModBuild): Promise<ModBuild> {
  if (isTerminal(row.status)) return row;
  let s: ServiceBuild | null;
  try {
    s = await svcGet(row.id);
  } catch {
    if (Date.now() - row.createdAt.getTime() > STALE_MS) {
      return db.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "unreachable", error: "We lost contact with the builder while this was running. Please try again.", finishedAt: new Date() } });
    }
    return row;
  }
  if (!s) {
    return db.modBuild.update({ where: { id: row.id }, data: { status: "failed", errorCode: "lost", error: "The builder has no record of this build. Please try again.", finishedAt: new Date() } });
  }
  const data: Prisma.ModBuildUpdateInput = {
    status: s.status,
    attempts: s.attempts || 0,
    costUsd: s.costUsd || 0,
    durationMs: s.durationMs || null,
    pluginName: s.pluginName || row.pluginName,
    version: s.version || row.version,
    error: s.error,
    errorCode: s.errorCode,
    result: toResult(s) as unknown as Prisma.InputJsonValue,
  };
  if (s.status === "succeeded" && s.jar) {
    // Store the jar before flipping the row to succeeded, so "succeeded" always
    // means "downloadable".
    const bytes = await svcArtifact(row.id);
    const sha = createHash("sha256").update(bytes).digest("hex");
    if (sha !== s.jar.sha256) throw new Error("artifact checksum mismatch");
    await mkdir(MODBUILD_DIR, { recursive: true, mode: 0o750 });
    const dest = jarPathFor(row.id);
    await writeFile(dest + ".part", bytes, { mode: 0o640 });
    await rename(dest + ".part", dest);
    Object.assign(data, { jarName: s.jar.name, jarSize: bytes.length, jarSha256: sha, jarPath: dest });
  }
  if (isTerminal(s.status)) data.finishedAt = s.finishedAt ? new Date(s.finishedAt) : new Date();
  return db.modBuild.update({ where: { id: row.id }, data });
}

export async function readJar(row: ModBuild): Promise<Buffer> {
  if (!row.jarPath || row.status !== "succeeded") throw new Error("no jar");
  return readFile(row.jarPath);
}

/** Worker sweep: advance every in-flight build. */
export async function sweepModBuilds(): Promise<void> {
  const rows = await db.modBuild.findMany({ where: { status: { notIn: ["succeeded", "failed"] } }, take: 20, orderBy: { createdAt: "asc" } });
  for (const r of rows) {
    try { await syncBuild(r); } catch (e) { console.error("[modbuilder] sync failed", r.id, (e as Error).message); }
  }
}

export function toView(row: ModBuild): ModBuildView {
  return {
    id: row.id,
    status: row.status as ModBuildView["status"],
    prompt: row.prompt,
    changeRequest: row.changeRequest,
    baseBuildId: row.baseBuildId,
    rootBuildId: row.rootBuildId,
    mcVersion: row.mcVersion,
    pluginName: row.pluginName,
    version: row.version,
    error: row.error,
    errorCode: row.errorCode,
    attempts: row.attempts,
    durationMs: row.durationMs,
    jarName: row.jarName,
    jarSize: row.jarSize,
    createdAt: row.createdAt.toISOString(),
    finishedAt: row.finishedAt ? row.finishedAt.toISOString() : null,
    result: (row.result as unknown as ModBuildResult) ?? null,
    lastInstall: (row.lastInstall as unknown as ModBuildView["lastInstall"]) ?? null,
  };
}
import { NextResponse } from "next/server";
import { randomBytes } from "node:crypto";
import { db } from "@/lib/db";
import { modBuilderUser } from "@/lib/modbuilder/access";
import { svcCreate, ModBuilderUnavailable } from "@/lib/modbuilder/client";
import { toView } from "@/lib/modbuilder/store";
import { MB_VERSIONS } from "@/lib/modbuilder/types";
import { checkRateLimit } from "@/lib/rate-limit";
import { NOT_FOUND } from "../_lib";

export const dynamic = "force-dynamic";

const MAX_INFLIGHT = 2;

export async function GET() {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const rows = await db.modBuild.findMany({ where: { userId: user.id }, orderBy: { createdAt: "desc" }, take: 50 });
  return NextResponse.json({ builds: rows.map(toView) });
}

export async function POST(req: Request) {
  const user = await modBuilderUser();
  if (!user) return NOT_FOUND();
  const body = (await req.json().catch(() => ({}))) as Record<string, unknown>;
  const prompt = String(body.prompt ?? "").trim();
  const mcVersion = String(body.mcVersion ?? MB_VERSIONS[0]);
  const changeRequest = body.changeRequest ? String(body.changeRequest).trim() : "";
  const baseBuildId = body.baseBuildId ? String(body.baseBuildId) : null;

  if (!(MB_VERSIONS as readonly string[]).includes(mcVersion)) return NextResponse.json({ error: "Pick a Minecraft version from the list." }, { status: 400 });

  let base = null;
  if (baseBuildId) {
    base = await db.modBuild.findUnique({ where: { id: baseBuildId } });
    if (!base || base.userId !== user.id) return NOT_FOUND();
    if (base.status !== "succeeded") return NextResponse.json({ error: "You can only change a build that finished." }, { status: 400 });
    if (changeRequest.length < 4 || changeRequest.length > 2000) return NextResponse.json({ error: "Describe the change in a few words (up to 2,000 characters)." }, { status: 400 });
  } else if (prompt.length < 12 || prompt.length > 4000) {
    return NextResponse.json({ error: prompt.length < 12 ? "Tell us a bit more about what the plugin should do." : "That's a lot! Keep it under 4,000 characters." }, { status: 400 });
  }

  for (const [k, max, windowMs] of [["mb:create:min", 3, 60_000], ["mb:create:hour", 20, 3_600_000]] as const) {
    const rl = checkRateLimit(`${k}:${user.id}`, { max, windowMs });
    if (!rl.ok) return NextResponse.json({ error: `You're building fast! Try again in ${rl.retryAfterSec}s.` }, { status: 429 });
  }
  const inflight = await db.modBuild.count({ where: { userId: user.id, status: { notIn: ["succeeded", "failed"] } } });
  if (inflight >= MAX_INFLIGHT) return NextResponse.json({ error: "You already have builds running. Wait for one to finish first." }, { status: 429 });

  const id = "mb" + randomBytes(10).toString("hex");
  const row = await db.modBuild.create({
    data: {
      id,
      userId: user.id,
      prompt: base ? base.prompt : prompt,
      changeRequest: base ? changeRequest : null,
      baseBuildId: base ? base.id : null,
      rootBuildId: base ? (base.rootBuildId ?? base.id) : id,
      mcVersion: base ? base.mcVersion : mcVersion,
      pluginName: base ? base.pluginName : null,
    },
  });
  try {
    await svcCreate({
      id,
      prompt: row.prompt,
      mcVersion: row.mcVersion,
      ...(base ? { baseBuildId: base.id, changeRequest } : {}),
    });
  } catch (e) {
    const msg = e instanceof ModBuilderUnavailable ? "The builder is offline right now. Please try again in a few minutes." : "The builder couldn't take this request. Please try again.";
    await db.modBuild.update({ where: { id }, data: { status: "failed", errorCode: "unavailable", error: msg, finishedAt: new Date() } });
    console.error("[modbuilder] create failed", id, (e as Error).message);
  }
  await db.auditLog.create({ data: { userId: user.id, action: base ? "modbuilder.change" : "modbuilder.build", detail: id } }).catch(() => {});
  const fresh = await db.modBuild.findUnique({ where: { id } });
  return NextResponse.json({ build: toView(fresh!) }, { status: 201 });
}
import { NextResponse } from "next/server";
import { syncBuild, toView } from "@/lib/modbuilder/store";
import { NOT_FOUND, ownedBuild } from "../../_lib";

export const dynamic = "force-dynamic";

export async function GET(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  let row = o.build;
  try { row = await syncBuild(row); } catch (e) { console.error("[modbuilder] sync", row.id, (e as Error).message); }
  return NextResponse.json({ build: toView(row) }, { headers: { "Cache-Control": "no-store" } });
}
import { NextResponse } from "next/server";
import { svcSource } from "@/lib/modbuilder/client";
import { NOT_FOUND, ownedBuild } from "../../../_lib";

export const dynamic = "force-dynamic";

// One source file as text, proxied from the build service (the source lives there).
export async function GET(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  const path = new URL(req.url).searchParams.get("path") || "";
  if (!/^[A-Za-z0-9_./-]{1,300}$/.test(path) || path.includes("..")) return NextResponse.json({ error: "Bad path" }, { status: 400 });
  try {
    const r = await svcSource(o.build.id, path);
    if (!r.ok) return NextResponse.json({ error: "File not found" }, { status: 404 });
    return new Response(await r.text(), { headers: { "Content-Type": "text/plain; charset=utf-8", "Cache-Control": "private, max-age=300", "X-Content-Type-Options": "nosniff" } });
  } catch {
    return NextResponse.json({ error: "The builder is offline right now." }, { status: 503 });
  }
}
import { NextResponse } from "next/server";
import { svcCancel } from "@/lib/modbuilder/client";
import { isTerminal } from "@/lib/modbuilder/types";
import { NOT_FOUND, ownedBuild } from "../../../_lib";

export async function POST(_req: Request, { params }: { params: Promise<{ id: string }> }) {
  const o = await ownedBuild((await params).id);
  if (!o) return NOT_FOUND();
  if (!isTerminal(o.build.status)) await svcCancel(o.build.id).catch(() => {});
  return NextResponse.json({ ok: true });
}

