async function classifyWithHaiku(rec, ctl, text) {
  const args = ["-p", "--output-format", "json", "--tools", "", "--strict-mcp-config", "--settings", SETTINGS,
    "--model", R.HAIKU, "--max-turns", "1", "--max-budget-usd", "0.05", "--system-prompt", R.CLASSIFIER_PROMPT, "--", `<request>\n${text}\n</request>`];
  const cwd = path.join(WORK, `${rec.id}-cls`);
  fs.mkdirSync(cwd, { recursive: true });
  const r = await run("claude", args, { cwd, env: childEnv(true), timeout: 60000, track: ctl });
  ctl.child = null;
  rmrf(cwd);
  let j = null; try { j = JSON.parse(r.out); } catch { /* fall through */ }
  const cost = j && typeof j.total_cost_usd === "number" ? j.total_cost_usd : 0;
  rec.costUsd = +(rec.costUsd + cost).toFixed(4);
  rec.aiCalls.push({ at: now(), kind: "classify", route: null, model: R.HAIKU, resolvedModel: R.HAIKU, costUsd: cost, turns: j ? j.num_turns : null, durationMs: j ? j.duration_ms : null, subtype: j ? j.subtype : null, exit: r.code });
  const word = j && typeof j.result === "string" ? (j.result.toLowerCase().match(/simple|standard|complex/) || [null])[0] : null;
  return word;
}

