function Modal({ title, sub, onClose, children }: { title: string; sub?: string; onClose: () => void; children: React.ReactNode }) {
  useEffect(() => {
    const k = (e: KeyboardEvent) => { if (e.key === "Escape") onClose(); };
    window.addEventListener("keydown", k);
    const prev = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    return () => { window.removeEventListener("keydown", k); document.body.style.overflow = prev; };
  }, [onClose]);
  return (
    <div className="mb-modal-back" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(e) => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="mb-modal card flex flex-col gap-4 p-5 sm:p-6">
        <div className="flex items-start gap-3">
          <div className="flex flex-col gap-1">
            <h2 className="text-[18px] font-extrabold tracking-[-0.01em] text-tx">{title}</h2>
            {sub && <p className="text-[12.5px] leading-[1.55] text-tx-faint">{sub}</p>}
          </div>
          <button type="button" className="ml-auto rounded-lg p-1.5 text-tx-faint hover:text-tx" onClick={onClose} aria-label="Close">
            <Icon name="xcircle" size={14} tone="inherit" />
          </button>
        </div>
        {children}
      </div>
    </div>
  );
}

export function InstallModal({ build, servers, onClose, onDone }: { build: ModBuildView; servers: MbServer[]; onClose: () => void; onDone: (b?: ModBuildView) => void }) {
  const firstOk = servers.find((s) => s.compatible);
  const [sel, setSel] = useState<string | null>(build.lastInstall?.serverId && servers.some((s) => s.id === build.lastInstall!.serverId && s.compatible) ? build.lastInstall.serverId : firstOk?.id ?? null);
  const chosen = servers.find((s) => s.id === sel);
  const [restart, setRestart] = useState(true);
  const [busy, setBusy] = useState(false);
  const [err, setErr] = useState<string | null>(null);
  const [done, setDone] = useState<null | { replaced: string[]; restarted: boolean; restartNote: string | null; path: string }>(null);

  async function go() {
    if (!sel) return;
    setBusy(true); setErr(null);
    try {
      const r = await fetch(`/api/mod-builder/builds/${build.id}/install`, {
        method: "POST", headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ serverId: sel, restart: restart && chosen?.status === "RUNNING" }),
      });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { setErr(j.error || "The install didn't go through."); setBusy(false); return; }
      setDone(j); setBusy(false); onDone();
    } catch { setErr("We couldn't reach Nxeon. Try again."); setBusy(false); }
