          </span>
          <p className="text-[14px] font-bold text-tx">{build.jarName} is on {chosen?.name}.</p>
          <p className="max-w-[46ch] text-[12.5px] leading-[1.6] text-tx-mute">
            {done.restarted ? "The server is restarting now. Your plugin loads as soon as it's back up (usually under a minute)."
              : done.restartNote ? `We couldn't restart it automatically: ${done.restartNote} Restart it from the server page to load the plugin.`
              : "Restart the server to load the plugin. Paper doesn't load new plugins while it's running."}
            {done.replaced.length > 0 && ` We replaced ${done.replaced.join(", ")} and kept a backup of it.`}
          </p>
          <div className="mt-1 flex flex-wrap justify-center gap-2.5">
            <Link href={`/dashboard/servers/${sel}`} className="mb-go">Open server <Icon name="external" size={12} tone="inherit" /></Link>
