      {servers.length === 0 ? (
        <div className="flex flex-col items-center gap-3 py-4 text-center">
          <Icon name="gamepad" size={22} tone="violet" />
          <p className="text-[13px] font-bold text-tx">You don&apos;t have a Minecraft server yet</p>
          <p className="max-w-[40ch] text-[12.5px] leading-[1.55] text-tx-faint">Download the .jar and put it in any Paper server&apos;s plugins folder, or start a Paper server on Nxeon.</p>
