                <input type="radio" name="mb-srv" className="sr-only" disabled={!s.compatible} checked={sel === s.id} onChange={() => setSel(s.id)} />
                <span className="mb-tile" style={{ width: 34, height: 34, borderRadius: 10 }}><Icon name="gamepad" size={13} tone={s.compatible ? "violet" : "slate"} /></span>
                <span className="flex min-w-0 flex-1 flex-col">
                  <span className="truncate text-[13px] font-bold text-tx">{s.name}</span>
                  <span className="text-[11.5px] text-tx-faint">{s.compatible ? `${cap(s.variant)} · ${s.status === "RUNNING" ? "online" : "stopped"}` : s.reason}</span>
