          </p>
          {err && <p role="alert" className="text-[12.5px] font-semibold text-[#ff8fa6]">{err}</p>}
          <div className="flex justify-end gap-2.5">
            <button type="button" className="btn-secondary" onClick={onClose}>Cancel</button>
            <button type="button" className="mb-go" disabled={!sel || busy} onClick={go}>
