    <Modal title="Ask for a change" sub={`We'll update ${build.pluginName} and keep everything that already works. You get a new version; this one stays as it is.`} onClose={onClose}>
      <textarea autoFocus value={text} onChange={(e) => setText(e.target.value)} rows={5} maxLength={2000}
                placeholder="e.g. “Also give players a golden apple on their 10th join, and make the welcome message purple.”"
                className="input w-full resize-y text-[13.5px] leading-[1.55]" />
      <div className="flex flex-wrap gap-2">
        {CHANGE_IDEAS.map((c) => (
          <button key={c} type="button" className="mb-who hover:text-tx" onClick={() => setText((t) => (t ? t.trimEnd() + " " : "") + c + ".")}>+ {c}</button>
        ))}
      </div>
      {err && <p role="alert" className="text-[12.5px] font-semibold text-[#ff8fa6]">{err}</p>}
      <div className="flex justify-end gap-2.5">
        <button type="button" className="btn-secondary" onClick={onClose}>Cancel</button>
        <button type="button" className="mb-go" disabled={busy || text.trim().length < 4} onClick={go}>
          {busy ? <Spinner /> : <Icon name="sparkles" size={13} tone="inherit" />} {busy ? "Starting…" : "Build the change"}
        </button>
      </div>
    </Modal>
  );
}

