type F = { path: string; size: number };

/** File tree + read-only code view, files fetched on demand from the build service (proxied). */
export function SourceViewer({ buildId, files, pluginName }: { buildId: string; files: F[]; pluginName?: string | null }) {
  const visible = useMemo(() => files.filter((f) => f.path.startsWith("src/") || f.path.endsWith(".kts")), [files]);
  const initial = useMemo(() => {
    const java = visible.filter((f) => f.path.endsWith(".java"));
    const main = pluginName ? java.find((f) => f.path.endsWith(`/${pluginName}.java`) || f.path.endsWith(`/${pluginName}Plugin.java`)) : undefined;
    return (main || java.find((f) => /Plugin\.java$|Main\.java$/.test(f.path)) || java[0] || visible[0])?.path ?? null;
  }, [visible, pluginName]);
  const [sel, setSel] = useState<string | null>(initial);
  const [cache, setCache] = useState<Record<string, string>>({});
  const [err, setErr] = useState<string | null>(null);

  useEffect(() => {
    if (!sel || cache[sel] !== undefined) return;
    let off = false;
    setErr(null);
    fetch(`/api/mod-builder/builds/${buildId}/source?path=${encodeURIComponent(sel)}`)
      .then(async (r) => { if (!r.ok) throw new Error(); return r.text(); })
      .then((t) => { if (!off) setCache((c) => ({ ...c, [sel]: t })); })
      .catch(() => { if (!off) setErr("Couldn't load this file right now."); });
    return () => { off = true; };
  }, [sel, buildId, cache]);

  // Group by folder, with the long Java package path collapsed to its last segment.
  const groups = useMemo(() => {
    const g = new Map<string, F[]>();
    for (const f of visible) {
      const parts = f.path.split("/");
      const dir = f.path.startsWith("src/main/java/") ? "Code" : f.path.startsWith("src/main/resources/") ? "Plugin files" : "Build";
      void parts;
      if (!g.has(dir)) g.set(dir, []);
      g.get(dir)!.push(f);
    }
    return Array.from(g.entries()).sort((a, b) => ["Code", "Plugin files", "Build"].indexOf(a[0]) - ["Code", "Plugin files", "Build"].indexOf(b[0]));
  }, [visible]);

  if (!visible.length) return <p className="text-[12.5px] text-tx-faint">No source files to show.</p>;
  const text = sel ? cache[sel] : undefined;
  const lang = sel?.endsWith(".java") ? "java" : sel?.endsWith(".yml") || sel?.endsWith(".yaml") ? "yaml" : "kts";

  return (
    <div className="mb-src nx-dark-island">
      <div className="mb-tree" role="tree" aria-label="Source files">
        {groups.map(([dir, fs]) => (
          <div key={dir}>
            <div className="dir">{dir}</div>
            {fs.map((f) => {
              const name = f.path.split("/").pop()!;
              return (
                <button key={f.path} type="button" className={sel === f.path ? "on" : ""} onClick={() => setSel(f.path)} title={f.path} role="treeitem" aria-selected={sel === f.path}>
                  <Icon name="file" size={11} tone={name.endsWith(".java") ? "violet" : "cyan"} />
                  <span className="truncate">{name}</span>
                </button>
              );
            })}
          </div>
        ))}
      </div>
      <div className="flex min-w-0 flex-col">
        <div className="flex items-center gap-2 border-b px-4 py-2 text-[11.5px] font-semibold text-[#8094c6]" style={{ borderColor: "rgba(140,180,255,.1)" }}>
          <span className="truncate">{sel}</span>
          {text !== undefined && (
            <button type="button" className="ml-auto inline-flex flex-none items-center gap-1 whitespace-nowrap rounded-md px-2 py-1 hover:bg-white/5 hover:text-white" onClick={() => navigator.clipboard?.writeText(text)}>
              <Icon name="copy" size={10} tone="inherit" /> Copy
            </button>
          )}
        </div>
        <div className="mb-code py-3">
          {err ? <p className="px-4 text-[12.5px] text-[#ff9fb3]">{err}</p>
            : text === undefined ? <p className="flex items-center gap-2 px-4 text-[12.5px] text-[#8094c6]"><Spinner size={12} /> Loading…</p>
            : (
              <table><tbody>
                {text.replace(/\n$/, "").split("\n").map((l, i) => (
                  <tr key={i}><td className="n">{i + 1}</td><td className="c">{highlight(l, lang)}</td></tr>
                ))}
              </tbody></table>
            )}
        </div>
      </div>
    </div>
  );
}

const JAVA_KW = new Set("abstract assert boolean break byte case catch char class const continue default do double else enum extends final finally float for if implements import instanceof int interface long native new null package private protected public return short static super switch synchronized this throw throws transient try var void volatile while true false record yield".split(" "));

/** Tiny per-line highlighter: React nodes only (no HTML injection). Block comments are styled per line. */
function highlight(line: string, lang: string): ReactNode[] {
  const out: ReactNode[] = [];
  let k = 0;
  if (lang === "yaml") {
    const m = line.match(/^(\s*)(#.*)$/);
    if (m) return [m[1], <span key="c" className="m">{m[2]}</span>];
    const kv = line.match(/^(\s*-?\s*)([\w.\-'"]+)(:)(.*)$/);
    if (kv) return [kv[1], <span key="k" className="t">{kv[2]}</span>, kv[3], <span key="v" className="s">{kv[4]}</span>];
    return [line];
  }
  const re = /(\/\/.*$|\/\*.*?\*\/|^\s*\*.*$|^\s*\/\*.*$)|("(?:\\.|[^"\\])*"|'(?:\\.|[^'\\])')|(@\w+)|\b([A-Za-z_]\w*)\b/g;
  let last = 0;
  for (let m; (m = re.exec(line)); ) {
    if (m.index > last) out.push(line.slice(last, m.index));
    if (m[1]) out.push(<span key={k++} className="m">{m[1]}</span>);
    else if (m[2]) out.push(<span key={k++} className="s">{m[2]}</span>);
    else if (m[3]) out.push(<span key={k++} className="a">{m[3]}</span>);
    else if (m[4] && JAVA_KW.has(m[4])) out.push(<span key={k++} className="k">{m[4]}</span>);
    else if (m[4] && /^[A-Z]/.test(m[4])) out.push(<span key={k++} className="t">{m[4]}</span>);
    else out.push(m[0]);
    last = m.index + m[0].length;
  }
  if (last < line.length) out.push(line.slice(last));
  return out;
}

