        <div className="flex flex-wrap items-center gap-2 text-[12px] font-semibold text-tx-faint">
          <span className="mb-who">Paper {b.mcVersion}</span>
          {b.version && <span className="mb-who">v{b.version}</span>}
          <span>Started <Ago iso={b.createdAt} /></span>
          {b.finishedAt && <span>· took {dur(b.durationMs)}</span>}
        </div>
        <blockquote className="max-w-[90ch] rounded-xl border px-4 py-3 text-[13px] leading-[1.6] text-tx-body" style={{ borderColor: "var(--color-rim-hi)", background: "var(--color-well)" }}>
          {b.changeRequest ? (
            <>
              <span className="mb-1 block text-[10.5px] font-extrabold uppercase tracking-[0.14em] text-tx-faint">Change you asked for</span>
              {b.changeRequest}
            </>
