// Cyrus: line diff between two versions of a file (pure, unit-tested).
// Myers O(ND) with a size guard; plugins are small (the service caps source at 1.5 MB).

export type DiffOp = { t: "eq" | "add" | "del"; a: number | null; b: number | null; text: string };

const MAX_LINES = 12000;
const MAX_D = 4000;

export function splitLines(s: string): string[] {
  if (!s) return [];
  const lines = s.replace(/\r\n?/g, "\n").split("\n");
  if (lines[lines.length - 1] === "") lines.pop();
  return lines;
}

export function diffLines(oldText: string, newText: string): DiffOp[] {
  const A = splitLines(oldText);
  const B = splitLines(newText);
  // Trim common prefix/suffix first: most version diffs touch a few lines.
  let pre = 0;
  while (pre < A.length && pre < B.length && A[pre] === B[pre]) pre++;
  let suf = 0;
  while (suf < A.length - pre && suf < B.length - pre && A[A.length - 1 - suf] === B[B.length - 1 - suf]) suf++;
  const a = A.slice(pre, A.length - suf);
  const b = B.slice(pre, B.length - suf);
  const mid = a.length + b.length > MAX_LINES ? replaceAll(a, b) : myers(a, b) ?? replaceAll(a, b);
  const out: DiffOp[] = [];
  for (let i = 0; i < pre; i++) out.push({ t: "eq", a: i + 1, b: i + 1, text: A[i] });
  for (const op of mid) out.push({ ...op, a: op.a === null ? null : op.a + pre, b: op.b === null ? null : op.b + pre });
  for (let i = 0; i < suf; i++) {
    const ai = A.length - suf + i, bi = B.length - suf + i;
    out.push({ t: "eq", a: ai + 1, b: bi + 1, text: A[ai] });
  }
  return out;
}

function replaceAll(a: string[], b: string[]): DiffOp[] {
  return [...a.map((text, i) => ({ t: "del" as const, a: i + 1, b: null, text })), ...b.map((text, i) => ({ t: "add" as const, a: null, b: i + 1, text }))];
}

/** Classic Myers with a stored trace; null when the edit distance exceeds MAX_D. 1-based line numbers. */
function myers(a: string[], b: string[]): DiffOp[] | null {
  const n = a.length, m = b.length, max = n + m;
  if (max === 0) return [];
  const off = max;
  let v = new Int32Array(2 * max + 2);
  const trace: Int32Array[] = [];
  let found = -1;
  for (let d = 0; d <= Math.min(max, MAX_D); d++) {
    trace.push(v.slice());
    const nv = v.slice();
    for (let k = -d; k <= d; k += 2) {
      let x = k === -d || (k !== d && v[off + k - 1] < v[off + k + 1]) ? v[off + k + 1] : v[off + k - 1] + 1;
      let y = x - k;
      while (x < n && y < m && a[x] === b[y]) { x++; y++; }
      nv[off + k] = x;
      if (x >= n && y >= m) { found = d; break; }
    }
    v = nv;
    if (found >= 0) { trace.push(v.slice()); break; }
  }
  if (found < 0) return null;
  // Backtrack.
  const ops: DiffOp[] = [];
  let x = n, y = m;
  for (let d = found; d > 0; d--) {
    const vv = trace[d];
    const k = x - y;
    const prevK = k === -d || (k !== d && vv[off + k - 1] < vv[off + k + 1]) ? k + 1 : k - 1;
    const prevX = vv[off + prevK];
    const prevY = prevX - prevK;
    while (x > prevX && y > prevY) { ops.push({ t: "eq", a: x, b: y, text: a[x - 1] }); x--; y--; }
    if (x === prevX) { ops.push({ t: "add", a: null, b: y, text: b[y - 1] }); y--; }
    else { ops.push({ t: "del", a: x, b: null, text: a[x - 1] }); x--; }
  }
  while (x > 0 && y > 0) { ops.push({ t: "eq", a: x, b: y, text: a[x - 1] }); x--; y--; }
  return ops.reverse();
}

export function diffStats(ops: DiffOp[]): { added: number; removed: number } {
  let added = 0, removed = 0;
  for (const o of ops) { if (o.t === "add") added++; else if (o.t === "del") removed++; }
  return { added, removed };
}

export type Hunk = { ops: DiffOp[]; skippedBefore: number };

/** Group ops into hunks with `ctx` lines of context; long equal runs collapse. */
export function hunks(ops: DiffOp[], ctx = 3): Hunk[] {
  const keep = new Array(ops.length).fill(false);
  ops.forEach((o, i) => {
    if (o.t === "eq") return;
    for (let j = Math.max(0, i - ctx); j <= Math.min(ops.length - 1, i + ctx); j++) keep[j] = true;
  });
  const out: Hunk[] = [];
  let skipped = 0;
  let cur: Hunk | null = null;
  ops.forEach((o, i) => {
    if (!keep[i]) { if (cur) { out.push(cur); cur = null; } skipped++; return; }
    if (!cur) { cur = { ops: [], skippedBefore: skipped }; skipped = 0; }
    cur.ops.push(o);
  });
  if (cur) out.push(cur);
  return out;
}

export type SideRow = { left: DiffOp | null; right: DiffOp | null };

/** Side-by-side rows: deletions pair with the additions that follow them. */
export function sideBySide(ops: DiffOp[]): SideRow[] {
  const rows: SideRow[] = [];
  let i = 0;
  while (i < ops.length) {
    const o = ops[i];
    if (o.t === "eq") { rows.push({ left: o, right: o }); i++; continue; }
    const dels: DiffOp[] = [], adds: DiffOp[] = [];
    while (i < ops.length && ops[i].t === "del") dels.push(ops[i++]);
    while (i < ops.length && ops[i].t === "add") adds.push(ops[i++]);
    for (let j = 0; j < Math.max(dels.length, adds.length); j++) rows.push({ left: dels[j] ?? null, right: adds[j] ?? null });
  }
  return rows;
}

export type FileChange = { path: string; kind: "added" | "removed" | "changed" | "same"; sizeA: number | null; sizeB: number | null };

/** Which files differ between two versions, from their file lists alone (size is a hint; content decides "same"). */
export function fileChanges(a: { path: string; size: number }[], b: { path: string; size: number }[]): FileChange[] {
  const ma = new Map(a.map((f) => [f.path, f.size]));
  const mb = new Map(b.map((f) => [f.path, f.size]));
  const paths = Array.from(new Set([...ma.keys(), ...mb.keys()])).sort();
  return paths.map((p) => {
    const sa = ma.has(p) ? ma.get(p)! : null;
    const sb = mb.has(p) ? mb.get(p)! : null;
    const kind = sa === null ? "added" : sb === null ? "removed" : sa === sb ? "same" : "changed";
    return { path: p, kind, sizeA: sa, sizeB: sb };
  });
}

