// Cyrus: reference images pasted into the prompt (server-only).
//
// Flow: the composer uploads each image as soon as it is pasted/dropped
// (POST /api/mod-builder/uploads) and gets an upload id; the create call sends
// `attachmentIds`, and the images move next to the build. Stored on the primary
// beside the jars (MODBUILD_DIR), never in the DB.
//
// NOT YET USED BY THE AI: the build service has no image input today. Images are
// stored, shown back to the owner, and ready to forward once the service accepts them.
import { randomBytes } from "node:crypto";
import { mkdir, readFile, rename, writeFile, stat, readdir, unlink } from "node:fs/promises";
import { join } from "node:path";
import { MODBUILD_DIR } from "../modbuilder/store";
import type { CyrusAttachment } from "./meta";

export const CYRUS_MAX_IMAGE_BYTES = 5 * 1024 * 1024;
export const CYRUS_MAX_IMAGES = 4;
const UPLOAD_TTL_MS = 24 * 60 * 60 * 1000;

const EXT: Record<string, string> = { "image/png": "png", "image/jpeg": "jpg", "image/webp": "webp", "image/gif": "gif" };

/** Real type from the file's first bytes (the browser's claim is not trusted). */
export function sniffImage(buf: Uint8Array): keyof typeof EXT | null {
  if (buf.length >= 8 && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47 && buf[4] === 0x0d && buf[5] === 0x0a && buf[6] === 0x1a && buf[7] === 0x0a) return "image/png";
  if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return "image/jpeg";
  if (buf.length >= 12 && buf[0] === 0x52 && buf[1] === 0x49 && buf[2] === 0x46 && buf[3] === 0x46 && buf[8] === 0x57 && buf[9] === 0x45 && buf[10] === 0x42 && buf[11] === 0x50) return "image/webp";
  if (buf.length >= 6 && buf[0] === 0x47 && buf[1] === 0x49 && buf[2] === 0x46 && buf[3] === 0x38 && (buf[4] === 0x37 || buf[4] === 0x39) && buf[5] === 0x61) return "image/gif";
  return null;
}

export const isUploadId = (s: unknown): s is string => typeof s === "string" && /^up[0-9a-f]{20}$/.test(s);
const userDir = (userId: string) => join(MODBUILD_DIR, "uploads", userId.replace(/[^A-Za-z0-9_-]/g, ""));
const buildDir = (buildId: string) => join(MODBUILD_DIR, "attachments", buildId.replace(/[^A-Za-z0-9_-]/g, ""));
const cleanName = (n: string) => (n || "image").replace(/[^\w.\- ()]/g, "").slice(0, 80) || "image";

export async function saveUpload(userId: string, name: string, bytes: Uint8Array): Promise<{ ok: true; id: string; type: string; size: number; name: string } | { ok: false; error: string }> {
  if (bytes.length === 0) return { ok: false, error: "That image is empty." };
  if (bytes.length > CYRUS_MAX_IMAGE_BYTES) return { ok: false, error: "Images can be up to 5 MB." };
  const type = sniffImage(bytes);
  if (!type) return { ok: false, error: "Use a PNG, JPG, WebP or GIF image." };
  const dir = userDir(userId);
  await mkdir(dir, { recursive: true, mode: 0o750 });
  void sweepOld(dir);
  const id = "up" + randomBytes(10).toString("hex");
  await writeFile(join(dir, `${id}.bin`), bytes, { mode: 0o640 });
  await writeFile(join(dir, `${id}.json`), JSON.stringify({ name: cleanName(name), type, size: bytes.length, at: Date.now() }), { mode: 0o640 });
  return { ok: true, id, type, size: bytes.length, name: cleanName(name) };
}

/** Move the user's uploads next to a new build. Unknown / foreign ids are skipped. */
export async function claimUploads(userId: string, buildId: string, ids: string[]): Promise<CyrusAttachment[]> {
  const out: CyrusAttachment[] = [];
  const src = userDir(userId);
  const dest = buildDir(buildId);
  for (const id of ids.filter(isUploadId).slice(0, CYRUS_MAX_IMAGES)) {
    try {
      const meta = JSON.parse(await readFile(join(src, `${id}.json`), "utf8")) as { name: string; type: string; size: number };
      if (!EXT[meta.type]) continue;
      await mkdir(dest, { recursive: true, mode: 0o750 });
      const n = out.length + 1;
      await rename(join(src, `${id}.bin`), join(dest, `${n}.${EXT[meta.type]}`));
      await unlink(join(src, `${id}.json`)).catch(() => {});
      out.push({ n, name: meta.name, type: meta.type, size: meta.size });
    } catch { /* gone or not this user's */ }
  }
  return out;
}

export async function readAttachment(buildId: string, a: CyrusAttachment): Promise<Buffer | null> {
  const ext = EXT[a.type];
  if (!ext) return null;
  try { return await readFile(join(buildDir(buildId), `${a.n}.${ext}`)); } catch { return null; }
}

async function sweepOld(dir: string) {
  try {
    for (const f of await readdir(dir)) {
      const p = join(dir, f);
      const s = await stat(p);
      if (Date.now() - s.mtimeMs > UPLOAD_TTL_MS) await unlink(p).catch(() => {});
    }
  } catch { /* best effort */ }
}

