// Cyrus: prompt templates gallery (client-safe). Every prompt is written to be
// buildable by the current service (plain Paper API, no other plugins needed).
import type { CyrusModelId } from "./models";

export type CyrusTemplate = { id: string; title: string; cat: "Economy" | "Gameplay" | "Admin" | "Social" | "World"; blurb: string; model: CyrusModelId; prompt: string };

export const CYRUS_TEMPLATE_CATS = ["All", "Gameplay", "Economy", "Social", "Admin", "World"] as const;

export const CYRUS_TEMPLATES: CyrusTemplate[] = [
  { id: "heal", cat: "Admin", title: "Heal & feed", model: "katara", blurb: "/heal and /feed with a cooldown", prompt: "A /heal command that fully heals the player who runs it and a /feed command that fills their hunger. Each has a 60 second cooldown per player, shown in an action bar message. Operators can heal or feed another player with /heal <name> and /feed <name>. Cooldowns are set in config.yml." },
  { id: "join", cat: "Social", title: "Welcome titles", model: "katara", blurb: "Big welcome for new players", prompt: "Custom join and leave messages. New players get a big welcome title and a different chat message than returning players. All messages are set in config.yml with placeholders for the player's name and how many players are online. Add /joinmsg reload for operators." },
  { id: "drops", cat: "World", title: "Lucky mob drops", model: "katara", blurb: "Rare drops from common mobs", prompt: "Custom mob drops: zombies have a 5% chance to drop an emerald, skeletons drop extra arrows and creepers sometimes drop a TNT block. All chances and items are set in config.yml, and /drops reload reloads them." },
  { id: "spawn", cat: "Admin", title: "Spawn & homes", model: "katara", blurb: "/spawn, /sethome, /home", prompt: "Handy player commands: /spawn teleports to the world spawn, /sethome and /home save and return to one home per player (saved between restarts), and /discord, /rules and /website print messages I can edit in config.yml." },
  { id: "streak", cat: "Social", title: "Daily streaks", model: "saka", blurb: "Rewards that grow each day", prompt: "Daily join rewards: the first time a player joins each day they get a reward that grows with their login streak (day 1: 5 bread, day 3: iron ingots, day 7: a diamond). Show a welcome title with their current streak. Streaks are saved. Add /streak to see your streak." },
  { id: "shop", cat: "Economy", title: "Coin shop", model: "saka", blurb: "Coins, /pay and a chest-menu shop", prompt: "A simple economy: every player has coins saved to disk. Commands: /balance, /pay <player> <amount>, /baltop (top 10). Players earn 1 coin for each hostile mob they kill. /shop opens a chest menu where players buy diamonds, golden apples and ender pearls for coins; prices are configurable in config.yml." },
  { id: "score", cat: "Gameplay", title: "Stats sidebar", model: "saka", blurb: "Kills, deaths, play time", prompt: "A sidebar scoreboard for every player showing the server name, their kills, deaths, K/D ratio, play time and how many players are online. Update it every 2 seconds. Kills, deaths and play time are saved so they survive restarts. The title and colours are configurable." },
  { id: "zones", cat: "World", title: "Protected zones", model: "saka", blurb: "Anti-grief areas", prompt: "Protected zones: operators mark two corners with /zone pos1 and /zone pos2 and save them with /zone create <name>. Inside a zone, players without permission can't break or place blocks, open chests, use flint and steel or explode TNT. /zone list and /zone delete <name>. Zones survive restarts." },
  { id: "spleef", cat: "Gameplay", title: "Spleef arena", model: "saka", blurb: "A classic mini-game", prompt: "A spleef mini-game. An operator sets up an arena with /spleef setarena and /spleef setlobby. Players join with /spleef join; when 2 or more players are waiting a 10 second countdown starts, the arena floor is reset to snow, everyone gets a diamond shovel, and the last player standing wins and is announced to the server." },
  { id: "boss", cat: "Gameplay", title: "Summoned boss", model: "yakko", blurb: "Phases, minions, boss bar", prompt: "A custom boss fight: operators run /summonboss to spawn a Wither Skeleton boss named 'The Hollow King' with 300 health and a boss bar visible to nearby players. At 66% health it summons 4 skeleton minions, at 33% it gains speed and strikes lightning near players every 10 seconds. When it dies, announce the top damage dealer and drop a configurable reward chest." },
  { id: "quests", cat: "Gameplay", title: "Quest board", model: "yakko", blurb: "Daily quests with rewards", prompt: "A daily quest system: each day every player gets 3 random quests from a list in config.yml (kill 20 zombies, mine 64 coal, fish 5 times, walk 2,000 blocks...). /quests opens a chest menu showing progress bars. Completing a quest gives its reward and a title. Progress is saved and quests reset at midnight server time." },
  { id: "chat", cat: "Social", title: "Chat tools", model: "saka", blurb: "Ranks, filter, /msg", prompt: "Chat improvements: a configurable chat format with ranks by permission, a word filter that replaces bad words with ***, /msg and /reply for private messages, and /mute <player> <minutes> for operators. Mutes are saved." },
];

