"use client";

// Cyrus "thinking" field: a living spiderweb network over an aurora.
// One small 2D canvas, no libraries. Nodes spring toward a per-mode layout, so
// the shape of the web itself says what Cyrus is doing:
//   idle / typing   loose drifting web (typing and voice add energy)
//   queued          the web gathers, slow
//   planning        thought pulses race along threads from the core
//   coding          the web crystallises into a lattice; every file the AI
//                   writes (a real build event) is born as a labelled node
//   compiling       concentric rings spin up
//   repairing       one node faults (rose), pulses converge on it and heal it
//   scanning        a radar sweep lights each node mint as it passes
//   succeeded       everything draws into a constellation and blooms
//   failed          the web loosens and dims
// Honours prefers-reduced-motion (one still frame), pauses off-screen and in
// hidden tabs, caps DPR, and reads its palette from CSS variables so the light
// theme gets its own colours.
import { useEffect, useRef } from "react";

export type NebulaMode = "idle" | "typing" | "listening" | "queued" | "planning" | "coding" | "compiling" | "repairing" | "scanning" | "succeeded" | "failed";

type Node = { x: number; y: number; vx: number; vy: number; hx: number; hy: number; r: number; tw: number; lit: number; label?: string; born: number; seedA: number; seedR: number };
type Pulse = { a: number; b: number; t: number; v: number; c: number };

const PAL_VARS = ["--cy-n1", "--cy-n2", "--cy-n3", "--cy-n4", "--cy-n5", "--cy-line-rgb", "--cy-label"];

function rng(seed: number) {
  let s = seed >>> 0 || 1;
  return () => { s ^= s << 13; s ^= s >>> 17; s ^= s << 5; return ((s >>> 0) % 100000) / 100000; };
}

export function Nebula({ mode, energy = 0, burst, burstLabel, seed = 7, density = 1, className = "", interactive = true }: {
  mode: NebulaMode; energy?: number; burst?: number; burstLabel?: string; seed?: number; density?: number; className?: string; interactive?: boolean;
}) {
  const ref = useRef<HTMLCanvasElement>(null);
  const st = useRef({ mode, energy, burst: burst ?? 0, burstLabel: burstLabel ?? "" });
  st.current.mode = mode;
  st.current.energy = energy;

  // Births from real build events.
  const pendingBirth = useRef<string[]>([]);
  const lastBurst = useRef(burst ?? 0);
  useEffect(() => {
    if (burst === undefined) return;
    if (burst > lastBurst.current) pendingBirth.current.push(burstLabel || "");
    lastBurst.current = burst;
  }, [burst, burstLabel]);

  useEffect(() => {
    const cv = ref.current;
    if (!cv) return;
    const ctx = cv.getContext("2d");
    if (!ctx) return;
    const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const rand = rng(seed * 2654435761);
    let W = 0, H = 0, dpr = 1;
    let pal: string[] = [];
    const readPal = () => {
      const cs = getComputedStyle(cv);
      pal = PAL_VARS.map((v) => cs.getPropertyValue(v).trim() || "#8fd8ff");
    };
    readPal();
    const mo = new MutationObserver(readPal);
    mo.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme", "class"] });

    const nodes: Node[] = [];
    const pulses: Pulse[] = [];
    let fault = -1;
    let sweep = 0;
    let bloom = 0;
    let t0 = performance.now();
    let last = t0;
    let mouse: { x: number; y: number } | null = null;

    const count = () => Math.round(Math.max(22, Math.min(76, (W * H) / 9000)) * density);
    const mk = (x: number, y: number, label?: string): Node => ({ x, y, vx: 0, vy: 0, hx: x, hy: y, r: 1 + rand() * 1.8, tw: rand() * Math.PI * 2, lit: 0, label, born: performance.now(), seedA: rand() * Math.PI * 2, seedR: rand() });

    const resize = () => {
      const r = cv.getBoundingClientRect();
      dpr = Math.min(window.devicePixelRatio || 1, W > 0 && r.width < 500 ? 1.25 : 1.5);
      W = Math.max(1, r.width); H = Math.max(1, r.height);
      cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      const want = count();
      while (nodes.length < want) nodes.push(mk(rand() * W, rand() * H));
      while (nodes.length > want + 12) nodes.pop();
      layout(performance.now());
    };

    // Per-mode home positions.
    const layout = (now: number) => {
      const m = st.current.mode;
      const cx = W / 2, cy = H / 2, R = Math.min(W, H) * 0.42;
      const n = nodes.length;
      const time = (now - t0) / 1000;
      nodes.forEach((p, i) => {
        let hx: number, hy: number;
        if (m === "coding") {
          // lattice: hex-ish grid centred, gently breathing
          const cols = Math.ceil(Math.sqrt(n * (W / H)));
          const rows = Math.ceil(n / cols);
          const gx = Math.min(W * 0.8 / Math.max(1, cols - 1), 70), gy = Math.min(H * 0.74 / Math.max(1, rows - 1), 60);
          const c = i % cols, r = Math.floor(i / cols);
          hx = cx + (c - (cols - 1) / 2) * gx + (r % 2 ? gx / 2 : 0) - gx / 4;
          hy = cy + (r - (rows - 1) / 2) * gy;
          hx += Math.sin(time * 0.8 + i) * 2;
        } else if (m === "compiling" || m === "repairing" || m === "scanning") {
          const rings = 4;
          const ring = i % rings;
          const per = Math.ceil(n / rings);
          const k = Math.floor(i / rings);
          const rr = R * (0.28 + ring * 0.24);
          const spin = m === "compiling" ? time * (0.35 + ring * 0.12) * (ring % 2 ? -1 : 1) : m === "repairing" ? time * 0.12 : 0;
          const a = (k / per) * Math.PI * 2 + ring * 0.7 + spin;
          hx = cx + Math.cos(a) * rr * (W > H ? 1.35 : 1);
          hy = cy + Math.sin(a) * rr * 0.92;
        } else if (m === "planning" || m === "queued") {
          const spread = m === "queued" ? 0.55 : 0.85;
          const a = p.seedA + time * 0.05;
          const rr = R * spread * Math.sqrt(p.seedR) * 1.25;
          hx = cx + Math.cos(a) * rr * (W > H ? 1.5 : 1);
          hy = cy + Math.sin(a) * rr;
        } else if (m === "succeeded") {
          // constellation: a calm ring with a bright core
          const a = p.seedA;
          const rr = R * (0.18 + 0.62 * p.seedR);
          hx = cx + Math.cos(a) * rr * (W > H ? 1.55 : 1);
          hy = cy + Math.sin(a) * rr * 0.9;
        } else if (m === "failed") {
          const a = p.seedA;
          const rr = R * (0.7 + 0.9 * p.seedR);
          hx = cx + Math.cos(a) * rr * 1.6;
          hy = cy + Math.sin(a) * rr;
        } else {
          // idle / typing / listening: field-wide drift
          hx = (p.seedA / (Math.PI * 2)) * W * 1.1 - W * 0.05 + Math.sin(time * 0.1 + i) * 14;
          hy = p.seedR * H * 1.1 - H * 0.05 + Math.cos(time * 0.12 + i * 1.7) * 10;
        }
        p.hx = hx; p.hy = hy;
      });
    };

    const colorFor = (m: NebulaMode, i: number) => {
      // n1 aurora teal, n2 cyan, n3 indigo, n4 violet, n5 magenta
      if (m === "failed") return pal[3];
      if (m === "scanning") return pal[i % 2 ? 0 : 1];
      if (m === "compiling") return pal[i % 3 === 0 ? 1 : 2];
      if (m === "coding") return pal[i % 4 === 0 ? 4 : 3];
      if (m === "succeeded") return pal[i % 3 === 0 ? 1 : 0];
      if (m === "listening") return pal[i % 2 ? 0 : 1];
      return pal[i % 5];
    };

    const neighbours = (i: number) => {
      const p = nodes[i];
      let best = -1, bd = Infinity;
      for (let j = 0; j < nodes.length; j++) {
        if (j === i) continue;
        const d = (nodes[j].x - p.x) ** 2 + (nodes[j].y - p.y) ** 2;
        if (d < bd && Math.random() < 0.6) { bd = d; best = j; }
      }
      return best;
    };

    const spawnPulse = (m: NebulaMode) => {
      if (nodes.length < 2) return;
      let a: number;
      if (m === "repairing" && fault >= 0) a = Math.floor(Math.random() * nodes.length);
      else if (m === "planning") a = Math.floor(Math.random() * Math.min(8, nodes.length));
      else a = Math.floor(Math.random() * nodes.length);
      const b = m === "repairing" && fault >= 0 ? fault : neighbours(a);
      if (b < 0) return;
      pulses.push({ a, b, t: 0, v: 0.9 + Math.random() * 1.4, c: Math.floor(Math.random() * 5) });
    };

    let prevMode = st.current.mode;
    let raf = 0, running = false, visible = true;

    const frame = (now: number) => {
      const dt = Math.min(0.05, (now - last) / 1000);
      last = now;
      const m = st.current.mode;
      if (m !== prevMode) {
        if (m === "repairing") fault = Math.floor(Math.random() * nodes.length);
        if (m !== "repairing") fault = -1;
        if (m === "succeeded") bloom = 1;
        prevMode = m;
      }
      // births from real events
      while (pendingBirth.current.length) {
        const label = pendingBirth.current.shift()!;
        const nn = mk(W / 2 + (Math.random() - 0.5) * 20, H / 2 + (Math.random() - 0.5) * 20, label || undefined);
        nn.lit = 1;
        nodes.push(nn);
        if (nodes.length > count() + 12) nodes.splice(0, 1);
        for (let k = 0; k < 4; k++) pulses.push({ a: nodes.length - 1, b: Math.floor(Math.random() * (nodes.length - 1)), t: 0, v: 1.6, c: 4 });
      }
      layout(now);
      const energy = st.current.energy;
      const stiff = m === "idle" || m === "typing" || m === "listening" ? 0.6 : m === "failed" ? 0.4 : 2.2;
      const jitter = (m === "listening" ? 30 : m === "typing" ? 14 : 4) * (0.4 + energy);
      for (const p of nodes) {
        p.vx += ((p.hx - p.x) * stiff - p.vx * 2.4) * dt + (Math.random() - 0.5) * jitter * dt;
        p.vy += ((p.hy - p.y) * stiff - p.vy * 2.4) * dt + (Math.random() - 0.5) * jitter * dt;
        if (mouse && interactive) {
          const dx = p.x - mouse.x, dy = p.y - mouse.y, d2 = dx * dx + dy * dy;
          if (d2 < 9000) { const f = (1 - d2 / 9000) * 60 * dt; p.vx += (dx / Math.sqrt(d2 + 1)) * f * 6; p.vy += (dy / Math.sqrt(d2 + 1)) * f * 6; p.lit = Math.max(p.lit, 0.5); }
        }
        p.x += p.vx * dt * 60 * 0.016 * 60;
        p.y += p.vy * dt * 60 * 0.016 * 60;
        p.tw += dt * (1 + p.seedR);
        p.lit = Math.max(0, p.lit - dt * 0.8);
      }
      // pulses
      const rate = { idle: 0.6, typing: 2.2, listening: 3.5, queued: 0.6, planning: 7, coding: 5, compiling: 4, repairing: 8, scanning: 2, succeeded: 1.2, failed: 0.15 }[m] * (1 + energy * 2);
      if (Math.random() < rate * dt) spawnPulse(m);
      if (m === "scanning") sweep = (sweep + dt * 1.6) % (Math.PI * 2);
      bloom = Math.max(0, bloom - dt * 0.45);
      draw(now, m);
      if (running) raf = requestAnimationFrame(frame);
    };

    const draw = (now: number, m: NebulaMode) => {
      ctx.clearRect(0, 0, W, H);
      const lineRgb = pal[5] || "140,170,255";
      const maxD = Math.min(150, Math.max(90, Math.min(W, H) * 0.28)) * (m === "coding" ? 0.95 : 1);
      const maxD2 = maxD * maxD;
      const dim = m === "failed" ? 0.45 : 1;
      // threads
      ctx.lineWidth = 1;
      for (let i = 0; i < nodes.length; i++) {
        const a = nodes[i];
        for (let j = i + 1; j < nodes.length; j++) {
          const b = nodes[j];
          const dx = a.x - b.x, dy = a.y - b.y, d2 = dx * dx + dy * dy;
          if (d2 > maxD2) continue;
          const k = 1 - d2 / maxD2;
          const glow = Math.max(a.lit, b.lit);
          ctx.strokeStyle = `rgba(${lineRgb},${((0.08 + k * 0.28) * dim + glow * 0.35).toFixed(3)})`;
          ctx.beginPath(); ctx.moveTo(a.x, a.y); ctx.lineTo(b.x, b.y); ctx.stroke();
        }
      }
      // pulses
      for (let i = pulses.length - 1; i >= 0; i--) {
        const q = pulses[i];
        const a = nodes[q.a], b = nodes[q.b];
        if (!a || !b) { pulses.splice(i, 1); continue; }
        q.t += 0.016 * q.v;
        if (q.t >= 1) {
          b.lit = Math.min(1, b.lit + 0.6);
          if (m === "repairing" && q.b === fault && Math.random() < 0.08) fault = -1;
          pulses.splice(i, 1); continue;
        }
        const x = a.x + (b.x - a.x) * q.t, y = a.y + (b.y - a.y) * q.t;
        const col = m === "repairing" && q.b === fault ? pal[4] : pal[q.c] || pal[1];
        ctx.fillStyle = col;
        ctx.globalAlpha = 0.9 * dim;
        ctx.beginPath(); ctx.arc(x, y, 1.8, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 0.25 * dim;
        ctx.beginPath(); ctx.arc(x, y, 5, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 1;
      }
      // radar sweep
      if (m === "scanning") {
        const cx = W / 2, cy = H / 2, R = Math.hypot(W, H) / 2;
        const g = ctx.createConicGradient ? ctx.createConicGradient(sweep - 0.6, cx, cy) : null;
        if (g) {
          g.addColorStop(0, "rgba(0,0,0,0)"); g.addColorStop(0.09, `${hexA(pal[0], 0.16)}`); g.addColorStop(0.1, "rgba(0,0,0,0)"); g.addColorStop(1, "rgba(0,0,0,0)");
          ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.fill();
        }
        for (const p of nodes) {
          const ang = (Math.atan2(p.y - cy, p.x - cx) + Math.PI * 2) % (Math.PI * 2);
          if (Math.abs(ang - sweep) < 0.08) p.lit = 1;
        }
      }
      // nodes
      nodes.forEach((p, i) => {
        const tw = 0.6 + 0.4 * Math.sin(p.tw * 2);
        const isFault = m === "repairing" && i === fault;
        const col = isFault ? pal[4] : p.lit > 0.4 && m === "scanning" ? pal[0] : colorFor(m, i);
        const r = p.r * (isFault ? 2.4 : 1) + p.lit * 1.6 + bloom * 1.2;
        ctx.fillStyle = col;
        ctx.globalAlpha = (0.12 + p.lit * 0.25 + bloom * 0.2) * dim;
        ctx.beginPath(); ctx.arc(p.x, p.y, r * 3.2, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = Math.min(1, (0.55 + tw * 0.45) * dim);
        ctx.beginPath(); ctx.arc(p.x, p.y, r, 0, Math.PI * 2); ctx.fill();
        ctx.globalAlpha = 1;
        if (p.label) {
          const age = (now - p.born) / 1000;
          if (age < 4.5) {
            ctx.globalAlpha = Math.max(0, Math.min(1, age * 3, (4.5 - age) / 1.2));
            ctx.font = "600 11px var(--font-nx-mono), ui-monospace, monospace";
            ctx.fillStyle = pal[6] || "#dfe8ff";
            ctx.fillText(p.label, p.x + 8, p.y - 8);
            ctx.globalAlpha = 1;
          }
        }
      });
      // core glow for building modes
      if (m === "planning" || m === "coding" || m === "compiling" || m === "repairing" || m === "succeeded" || m === "listening") {
        const cx = W / 2, cy = H / 2;
        const pulse = 0.5 + 0.5 * Math.sin(now / (m === "listening" ? 180 : 600));
        const rad = Math.min(W, H) * (0.16 + 0.05 * pulse + bloom * 0.25 + (m === "listening" ? st.current.energy * 0.12 : 0));
        const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, rad);
        const c = m === "repairing" ? pal[4] : m === "succeeded" || m === "listening" ? pal[0] : m === "compiling" ? pal[1] : pal[3];
        g.addColorStop(0, hexA(c, 0.32 + bloom * 0.3)); g.addColorStop(1, hexA(c, 0));
        ctx.fillStyle = g; ctx.beginPath(); ctx.arc(cx, cy, rad, 0, Math.PI * 2); ctx.fill();
      }
    };

    const start = () => { if (running || reduce) return; running = true; last = performance.now(); raf = requestAnimationFrame(frame); };
    const stop = () => { running = false; cancelAnimationFrame(raf); };

    resize();
    // settle into the mode's layout before the first paint
    for (let k = 0; k < 90; k++) { layout(t0); for (const p of nodes) { p.x += (p.hx - p.x) * 0.08; p.y += (p.hy - p.y) * 0.08; } }
    draw(performance.now(), st.current.mode);
    const ro = new ResizeObserver(() => { resize(); if (reduce || !running) draw(performance.now(), st.current.mode); });
    ro.observe(cv);
    const io = new IntersectionObserver(([e]) => { visible = e.isIntersecting; if (visible && document.visibilityState === "visible") start(); else stop(); });
    io.observe(cv);
    const vis = () => { if (document.visibilityState === "visible" && visible) start(); else stop(); };
    document.addEventListener("visibilitychange", vis);
    const mm = (e: PointerEvent) => { const r = cv.getBoundingClientRect(); mouse = { x: e.clientX - r.left, y: e.clientY - r.top }; };
    const ml = () => { mouse = null; };
    const host = cv.parentElement;
    if (interactive && host) { host.addEventListener("pointermove", mm); host.addEventListener("pointerleave", ml); }
    // reduced motion: repaint the still frame when the mode changes
    let still: number | undefined;
    if (reduce) still = window.setInterval(() => { if (prevMode !== st.current.mode) { prevMode = st.current.mode; for (let k = 0; k < 90; k++) { layout(t0); for (const p of nodes) { p.x += (p.hx - p.x) * 0.08; p.y += (p.hy - p.y) * 0.08; } } draw(performance.now(), st.current.mode); } }, 400);
    start();
    return () => {
      stop(); ro.disconnect(); io.disconnect(); mo.disconnect();
      document.removeEventListener("visibilitychange", vis);
      if (host) { host.removeEventListener("pointermove", mm); host.removeEventListener("pointerleave", ml); }
      if (still) clearInterval(still);
      t0 = 0;
    };
  }, [seed, density, interactive]);

  return <canvas ref={ref} className={`cy-nebula ${className}`} aria-hidden="true" />;
}

function hexA(c: string, a: number): string {
  const m = c.match(/^#([0-9a-f]{6})$/i);
  if (!m) return c;
  const n = parseInt(m[1], 16);
  return `rgba(${n >> 16},${(n >> 8) & 255},${n & 255},${a.toFixed(3)})`;
}

