"use client";

import { useMemo } from "react";
import { hashSeed } from "@/lib/cyrus/projects";

/**
 * A project's own constellation: 5-7 stars and their threads, derived from the
 * project id, so every mod is recognisable at a glance in the switcher.
 * `progress` (0..1) draws a live ring while a build runs.
 */
export function Glyph({ id, size = 36, state = "idle", progress }: { id: string; size?: number; state?: "idle" | "running" | "ok" | "bad"; progress?: number }) {
  const g = useMemo(() => {
    let h = hashSeed(id);
    const r = () => { h ^= h << 13; h ^= h >>> 17; h ^= h << 5; return ((h >>> 0) % 1000) / 1000; };
    const n = 5 + Math.floor(r() * 3);
    const pts = Array.from({ length: n }, (_, i) => {
      const a = (i / n) * Math.PI * 2 + r() * 0.9;
      const d = 5 + r() * 9;
      return { x: 18 + Math.cos(a) * d, y: 18 + Math.sin(a) * d, s: 0.9 + r() * 1.3 };
    });
    const edges: [number, number][] = [];
    for (let i = 0; i < n; i++) {
      let best = -1, bd = Infinity;
      for (let j = 0; j < n; j++) {
        if (j === i) continue;
        const d = (pts[i].x - pts[j].x) ** 2 + (pts[i].y - pts[j].y) ** 2;
        if (d < bd && !edges.some(([a, b]) => (a === j && b === i))) { bd = d; best = j; }
      }
      if (best >= 0) edges.push([i, best]);
      if (r() > 0.6) edges.push([i, (i + 2) % n]);
    }
    const hue = Math.floor(r() * 3);
    return { pts, edges, hue };
  }, [id]);
  const c = ["var(--cy-n1)", "var(--cy-n3)", "var(--cy-n5)"];
  const circ = 2 * Math.PI * 16.5;
  return (
    <span className={`cy-glyph cy-glyph-${state}`} style={{ width: size, height: size }}>
      <svg viewBox="0 0 36 36" width={size} height={size} aria-hidden="true">
        <defs>
          <radialGradient id={`gg-${id}`} cx="50%" cy="50%" r="60%">
            <stop offset="0" stopColor={c[g.hue]} stopOpacity=".28" />
            <stop offset="1" stopColor={c[g.hue]} stopOpacity="0" />
          </radialGradient>
        </defs>
        <circle cx="18" cy="18" r="17" fill={`url(#gg-${id})`} />
        {g.edges.map(([a, b], i) => (
          <line key={i} x1={g.pts[a].x} y1={g.pts[a].y} x2={g.pts[b].x} y2={g.pts[b].y} stroke="var(--cy-thread)" strokeWidth=".7" />
        ))}
        {g.pts.map((p, i) => (
          <circle key={i} cx={p.x} cy={p.y} r={p.s} fill={c[(i + g.hue) % 3]} className="cy-star" style={{ animationDelay: `${(i * 0.37) % 2}s` }} />
        ))}
        {state === "running" && (
          <circle cx="18" cy="18" r="16.5" fill="none" stroke="var(--cy-n1)" strokeWidth="1.4" strokeLinecap="round"
                  strokeDasharray={`${Math.max(0.06, progress ?? 0.1) * circ} ${circ}`} transform="rotate(-90 18 18)" className="cy-glyph-ring" />
        )}
      </svg>
    </span>
  );
}

