"use client";

// Voice to text for the Cyrus prompt. Web Speech API (Chrome, Edge, Safari)
// for the words; a separate getUserMedia analyser for the live level that
// drives the aurora waveform. Either can be missing: no recognition -> the mic
// button explains why; no analyser -> the waveform animates without real levels.
import { useCallback, useEffect, useRef, useState } from "react";

type SR = {
  continuous: boolean; interimResults: boolean; lang: string;
  start(): void; stop(): void; abort(): void;
  onresult: ((e: { resultIndex: number; results: ArrayLike<ArrayLike<{ transcript: string }> & { isFinal: boolean }> }) => void) | null;
  onerror: ((e: { error: string }) => void) | null;
  onend: (() => void) | null;
};

export function speechSupported(): boolean {
  if (typeof window === "undefined") return false;
  const w = window as unknown as { SpeechRecognition?: unknown; webkitSpeechRecognition?: unknown };
  return !!(w.SpeechRecognition || w.webkitSpeechRecognition);
}

export function useVoice(onFinal: (text: string) => void) {
  const [supported, setSupported] = useState(false);
  const [listening, setListening] = useState(false);
  const [interim, setInterim] = useState("");
  const [error, setError] = useState<string | null>(null);
  const level = useRef(0);
  const rec = useRef<SR | null>(null);
  const audio = useRef<{ ctx: AudioContext; stream: MediaStream; raf: number } | null>(null);
  const finalCb = useRef(onFinal);
  finalCb.current = onFinal;

  useEffect(() => { setSupported(speechSupported()); }, []);

  const stopAudio = () => {
    const a = audio.current;
    if (!a) return;
    cancelAnimationFrame(a.raf);
    a.stream.getTracks().forEach((t) => t.stop());
    a.ctx.close().catch(() => {});
    audio.current = null;
    level.current = 0;
  };

  const stop = useCallback(() => {
    try { rec.current?.stop(); } catch { /* already stopped */ }
    stopAudio();
    setListening(false);
    setInterim("");
  }, []);

  const start = useCallback(async () => {
    setError(null);
    const w = window as unknown as { SpeechRecognition?: new () => SR; webkitSpeechRecognition?: new () => SR };
    const Ctor = w.SpeechRecognition || w.webkitSpeechRecognition;
    if (!Ctor) { setError("Voice typing needs Chrome, Edge or Safari. You can still type or paste."); return; }
    const r = new Ctor();
    r.continuous = true;
    r.interimResults = true;
    r.lang = navigator.language || "en-US";
    r.onresult = (e) => {
      let fin = "", mid = "";
      for (let i = e.resultIndex; i < e.results.length; i++) {
        const res = e.results[i];
        if (res.isFinal) fin += res[0].transcript; else mid += res[0].transcript;
      }
      if (fin.trim()) finalCb.current(fin.trim());
      setInterim(mid);
    };
    r.onerror = (e) => {
      if (e.error === "not-allowed" || e.error === "service-not-allowed") setError("Microphone access is blocked. Allow it in your browser's address bar to talk to Cyrus.");
      else if (e.error === "no-speech") setError("Didn't catch that. Try again a little closer to the mic.");
      else if (e.error !== "aborted") setError("Voice typing stopped unexpectedly.");
    };
    r.onend = () => { stopAudio(); setListening(false); setInterim(""); };
    rec.current = r;
    try { r.start(); setListening(true); } catch { setError("Voice typing couldn't start."); return; }
    // Live level for the waveform (best effort; recognition works without it).
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: { echoCancellation: true, noiseSuppression: true } });
      const ctx = new AudioContext();
      const an = ctx.createAnalyser();
      an.fftSize = 512;
      ctx.createMediaStreamSource(stream).connect(an);
      const buf = new Uint8Array(an.fftSize);
      const tick = () => {
        an.getByteTimeDomainData(buf);
        let sum = 0;
        for (let i = 0; i < buf.length; i++) { const v = (buf[i] - 128) / 128; sum += v * v; }
        const rms = Math.sqrt(sum / buf.length);
        level.current = level.current * 0.7 + Math.min(1, rms * 5) * 0.3;
        if (audio.current) audio.current.raf = requestAnimationFrame(tick);
      };
      audio.current = { ctx, stream, raf: requestAnimationFrame(tick) };
    } catch { /* no analyser: the waveform runs on its own */ }
  }, []);

  useEffect(() => () => { try { rec.current?.abort(); } catch { /* noop */ } stopAudio(); }, []);

  return { supported, listening, interim, error, level, start, stop, toggle: () => (listening ? stop() : start()), clearError: () => setError(null) };
}

