"use client";

// Source file fetching for Cyrus (code pane + diff). Finished builds never change,
// so their files are cached for the session; an in-flight build's files are
// fetched with no-store and keyed by size so a rewrite is picked up.
import { useEffect, useState } from "react";

const cache = new Map<string, string>();
const inflight = new Map<string, Promise<string>>();

export function fetchSource(buildId: string, path: string, opts: { live?: boolean; sizeKey?: number } = {}): Promise<string> {
  const key = `${buildId}:${path}${opts.live ? `:${opts.sizeKey ?? 0}` : ""}`;
  if (cache.has(key)) return Promise.resolve(cache.get(key)!);
  if (inflight.has(key)) return inflight.get(key)!;
  const p = fetch(`/api/mod-builder/builds/${buildId}/source?path=${encodeURIComponent(path)}`, { cache: opts.live ? "no-store" : "default" })
    .then(async (r) => { if (!r.ok) throw new Error(String(r.status)); return r.text(); })
    .then((t) => { cache.set(key, t); inflight.delete(key); return t; })
    .catch((e) => { inflight.delete(key); throw e; });
  inflight.set(key, p);
  return p;
}

export function useSource(buildId: string | null, path: string | null, opts: { live?: boolean; sizeKey?: number } = {}) {
  const [state, setState] = useState<{ key: string; text?: string; error?: boolean }>({ key: "" });
  const key = buildId && path ? `${buildId}:${path}:${opts.live ? opts.sizeKey ?? 0 : "f"}` : "";
  useEffect(() => {
    if (!buildId || !path) return;
    let off = false;
    fetchSource(buildId, path, opts)
      .then((text) => { if (!off) setState({ key, text }); })
      .catch(() => { if (!off) setState({ key, error: true }); });
    return () => { off = true; };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [key]);
  return state.key === key ? state : { key, text: undefined, error: false };
}

