"use client";

import { useEffect, useMemo, useRef, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { CyIcon } from "./icons";
import { highlight, langOf } from "./highlight";
import { useSource } from "./source";

type F = { path: string; size: number; name: string; state: "ready" | "writing" | "written" | "editing" | "base"; src: string | null };

const EV = /^(Wrote|Edited|Reading) (.+)$/;

/** Files the AI touched so far, from the real build events ("Wrote Main.java", "Edited config.yml"). */
export function touchedFiles(b: ModBuildView): { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }[] {
  const out = new Map<string, { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }>();
  for (const e of b.result?.events ?? []) {
    const m = e.message.match(EV);
    if (!m) continue;
    const verb = m[1] as "Wrote" | "Edited" | "Reading";
    const prev = out.get(m[2]);
    if (verb === "Reading" && prev) continue;
    out.set(m[2], { name: m[2], verb: prev && prev.verb !== "Reading" && verb === "Reading" ? prev.verb : verb, at: e.at });
  }
  return Array.from(out.values());
}

const visibleSrc = (files: { path: string; size: number }[]) => files.filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json" || f.path.endsWith(".kts"));

export function CodePane({ build, base, height = 520, revealKey }: { build: ModBuildView; base?: ModBuildView | null; height?: number; revealKey?: string }) {
  const running = !isTerminal(build.status);
  const real = visibleSrc(build.result?.files ?? []);
  const touched = touchedFiles(build);

  const files: F[] = useMemo(() => {
    if (real.length) {
      const t = new Set(touched.filter((x) => x.verb !== "Reading").map((x) => x.name));
      return real.map((f) => {
        const name = f.path.split("/").pop()!;
        return { path: f.path, size: f.size, name, state: running && t.has(name) ? "written" : "ready", src: build.id };
      });
    }
    // Mid-build: the service shares file NAMES live (events); contents arrive at the end.
    const baseFiles = visibleSrc(base?.result?.files ?? []);
    const out: F[] = baseFiles.map((f) => {
      const name = f.path.split("/").pop()!;
      const hit = touched.find((x) => x.name === name && x.verb !== "Reading");
      return { path: f.path, size: f.size, name, state: hit ? "editing" : "base", src: base!.id };
    });
    for (const t of touched) {
