const EV = /^(Wrote|Edited|Reading) (.+)$/;

/** Files the AI touched so far, from the real build events ("Wrote Main.java", "Edited config.yml"). */
export function touchedFiles(b: ModBuildView): { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }[] {
  const out = new Map<string, { name: string; verb: "Wrote" | "Edited" | "Reading"; at: string }>();
  for (const e of b.result?.events ?? []) {
    const m = e.message.match(EV);
    if (!m) continue;
    const verb = m[1] as "Wrote" | "Edited" | "Reading";
    const prev = out.get(m[2]);
    if (verb === "Reading" && prev) continue;
    out.set(m[2], { name: m[2], verb: prev && prev.verb !== "Reading" && verb === "Reading" ? prev.verb : verb, at: e.at });
  }
  return Array.from(out.values());
}

const visibleSrc = (files: { path: string; size: number }[]) => files.filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json" || f.path.endsWith(".kts"));

