  return (
    <div className="cy-code nx-dark-island" style={{ ["--cy-code-h" as string]: `${height}px` }}>
      <div className="cy-code-head">
        <span className="cy-code-title"><CyIcon name="code" size={14} /> Workspace</span>
        {running ? (
          <span className="cy-live"><i /> Live</span>
        ) : (
          <span className="cy-code-count">{files.length} files</span>
        )}
        {running && writingCount > 0 && <span className="cy-code-count">{writingCount} touched</span>}
        {lines && (
          <button type="button" className="cy-code-btn" onClick={() => navigator.clipboard?.writeText(src.text || "")}>
            <CyIcon name="copy" size={12} /> Copy
          </button>
        )}
      </div>
      <div className="cy-code-body">
        <nav className="cy-tree" aria-label="Files">
          {files.length === 0 && (
