"use client";

import { useEffect, useMemo, useState } from "react";
import type { ModBuildView } from "@/lib/modbuilder/types";
import { diffLines, diffStats, fileChanges, hunks, sideBySide, type DiffOp } from "@/lib/cyrus/diff";
import { CyIcon } from "./icons";
import { highlight, langOf } from "./highlight";
import { fetchSource } from "./source";

type Row = { path: string; kind: "added" | "removed" | "changed" | "same"; ops: DiffOp[] | null; added: number; removed: number };

const src = (b: ModBuildView) => (b.result?.files ?? []).filter((f) => f.path.startsWith("src/") || f.path === "modbuilder.json");

export function DiffView({ a, b, labelA, labelB }: { a: ModBuildView; b: ModBuildView; labelA: string; labelB: string }) {
  const [rows, setRows] = useState<Row[] | null>(null);
  const [err, setErr] = useState(false);
  const [sel, setSel] = useState<string | null>(null);
  const [split, setSplit] = useState(true);
  const [showSame, setShowSame] = useState(false);

  useEffect(() => {
    let off = false;
    setRows(null); setErr(false);
    const ch = fileChanges(src(a), src(b));
    Promise.all(ch.map(async (c) => {
      const [ta, tb] = await Promise.all([
        c.sizeA === null ? "" : fetchSource(a.id, c.path),
        c.sizeB === null ? "" : fetchSource(b.id, c.path),
      ]);
      const ops = diffLines(ta, tb);
      const st = diffStats(ops);
      const kind: Row["kind"] = c.kind === "added" || c.kind === "removed" ? c.kind : st.added + st.removed ? "changed" : "same";
      return { path: c.path, kind, ops, ...st };
    }))
      .then((r) => { if (off) return; setRows(r); const first = r.find((x) => x.kind !== "same"); setSel(first?.path ?? r[0]?.path ?? null); })
      .catch(() => { if (!off) setErr(true); });
    return () => { off = true; };
  }, [a, b]);

  useEffect(() => { if (window.matchMedia("(max-width: 760px)").matches) setSplit(false); }, []);

  const totals = useMemo(() => (rows ?? []).reduce((t, r) => ({ added: t.added + r.added, removed: t.removed + r.removed, files: t.files + (r.kind === "same" ? 0 : 1) }), { added: 0, removed: 0, files: 0 }), [rows]);
  const cur = rows?.find((r) => r.path === sel) ?? null;
  const list = (rows ?? []).filter((r) => showSame || r.kind !== "same");

  return (
    <div className="cy-diff nx-dark-island">
      <div className="cy-diff-head">
        <span className="cy-diff-v a">{labelA}</span>
        <CyIcon name="chevr" size={14} />
        <span className="cy-diff-v b">{labelB}</span>
        {rows && (
          <span className="cy-diff-tot">
            {totals.files} file{totals.files === 1 ? "" : "s"} changed <b className="add">+{totals.added}</b> <b className="del">−{totals.removed}</b>
          </span>
        )}
        <span className="ml-auto flex items-center gap-1">
          <button type="button" className={`cy-seg ${split ? "on" : ""}`} onClick={() => setSplit(true)}>Side by side</button>
          <button type="button" className={`cy-seg ${!split ? "on" : ""}`} onClick={() => setSplit(false)}>Unified</button>
        </span>
      </div>
      {err ? <p className="cy-view-err">Couldn&apos;t load the two versions right now.</p>
        : !rows ? <div className="cy-diff-load"><i className="cy-spin" /> Comparing every file…</div>
        : (
          <div className="cy-diff-body">
            <nav className="cy-tree">
              {list.map((r) => (
                <button key={r.path} type="button" className={`cy-tree-f ${sel === r.path ? "on" : ""}`} onClick={() => setSel(r.path)} title={r.path}>
                  <span className={`cy-dk ${r.kind}`}>{r.kind === "added" ? "A" : r.kind === "removed" ? "D" : r.kind === "changed" ? "M" : "="}</span>
                  <span className="truncate">{r.path.split("/").pop()}</span>
                  {r.kind !== "same" && <span className="cy-dn"><b className="add">+{r.added}</b><b className="del">−{r.removed}</b></span>}
                </button>
              ))}
              {rows.some((r) => r.kind === "same") && (
                <button type="button" className="cy-follow" onClick={() => setShowSame((v) => !v)}>{showSame ? "Hide" : "Show"} {rows.filter((r) => r.kind === "same").length} unchanged</button>
              )}
              {totals.files === 0 && <p className="cy-tree-note">These two versions have identical source.</p>}
            </nav>
            <div className="cy-view">
              <div className="cy-view-path"><span className="truncate">{cur?.path}</span></div>
              <div className="cy-view-scroll">{cur?.ops && <Hunks ops={cur.ops} split={split} lang={langOf(cur.path)} />}</div>
            </div>
          </div>
        )}
    </div>
  );
}

function Hunks({ ops, split, lang }: { ops: DiffOp[]; split: boolean; lang: string }) {
  const hs = useMemo(() => hunks(ops, 3), [ops]);
  if (!hs.length || ops.every((o) => o.t === "eq")) return <p className="cy-view-err dim">No changes in this file.</p>;
  return (
    <table className={`cy-dl ${split ? "split" : "uni"}`}>
      <tbody>
        {hs.map((h, hi) => (
          <HunkRows key={hi} h={h.ops} skipped={h.skippedBefore} split={split} lang={lang} />
        ))}
      </tbody>
    </table>
  );
}

function HunkRows({ h, skipped, split, lang }: { h: DiffOp[]; skipped: number; split: boolean; lang: string }) {
  const sep = skipped > 0 ? <tr className="sep"><td colSpan={split ? 4 : 3}>⋯ {skipped} unchanged line{skipped === 1 ? "" : "s"}</td></tr> : null;
  if (!split) {
    return (
      <>
        {sep}
        {h.map((o, i) => (
          <tr key={i} className={o.t}>
            <td className="n">{o.a ?? ""}</td><td className="n">{o.b ?? ""}</td>
            <td className="c"><span className="sg">{o.t === "add" ? "+" : o.t === "del" ? "−" : " "}</span>{highlight(o.text, lang)}</td>
          </tr>
        ))}
      </>
    );
  }
  return (
    <>
      {sep}
      {sideBySide(h).map((r, i) => (
        <tr key={i}>
          <td className="n">{r.left?.a ?? ""}</td>
          <td className={`c half ${r.left ? r.left.t : "empty"}`}>{r.left ? highlight(r.left.text, lang) : null}</td>
          <td className="n">{r.right?.b ?? ""}</td>
          <td className={`c half ${r.right ? r.right.t : "empty"}`}>{r.right ? highlight(r.right.text, lang) : null}</td>
        </tr>
      ))}
    </>
  );
}

