"use client";

import { useEffect, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { CYRUS_STAGES } from "@/lib/cyrus/models";
import { hashSeed } from "@/lib/cyrus/projects";
import { Nebula, type NebulaMode } from "./Nebula";
import { CyIcon } from "./icons";
import { dur } from "./util";

const ORDER = ["queued", "planning", "coding", "compiling", "repairing", "scanning", "succeeded"];
export const PROGRESS: Record<string, number> = { queued: 0.04, planning: 0.14, coding: 0.4, compiling: 0.62, repairing: 0.72, scanning: 0.88, succeeded: 1, failed: 1 };

const HEADLINE: Record<string, string> = {
  queued: "Waiting for a free builder",
  planning: "Mapping out your mod",
  coding: "Weaving the code",
  compiling: "Compiling it into a real plugin",
  repairing: "Found a problem, fixing it",
  scanning: "Running the safety check",
  succeeded: "Your mod is ready",
  failed: "This one didn't build",
};

export const modeOf = (s: string): NebulaMode => (s === "queued" || s === "planning" || s === "coding" || s === "compiling" || s === "repairing" || s === "scanning" || s === "succeeded" || s === "failed" ? s : "idle");

/** The living "thinking" panel: nebula that reacts to the real stage + the build's own event stream. */
export function Stage({ build, compact = false }: { build: ModBuildView; compact?: boolean }) {
  const events = build.result?.events ?? [];
  const running = !isTerminal(build.status);
  const writes = events.filter((e) => /^(Wrote|Edited) /.test(e.message));
  const lastWrite = writes[writes.length - 1]?.message.replace(/^(Wrote|Edited) /, "") ?? "";
  const startedAt = events.find((e) => e.stage !== "queued")?.at ?? null;
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => { if (!running) return; const t = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(t); }, [running]);
  const elapsed = running && startedAt ? now - new Date(startedAt).getTime() : build.durationMs ?? 0;
  const stream = events.filter((e) => e.stage !== "queued" && e.message && e.message !== "Error details").slice(-5);
  const seen = new Set(events.map((e) => e.stage));
  const idx = ORDER.indexOf(build.status);
  const repairs = build.result?.repairs ?? 0;
  const head = build.status === "queued" && build.result?.queuePosition ? `In line · position ${build.result.queuePosition}` : HEADLINE[build.status] ?? "Working";

  return (
    <section className={`cy-stage ${compact ? "compact" : ""} st-${build.status}`} aria-live="polite" aria-label="Build progress">
      <div className="cy-aurora" aria-hidden="true"><i /><i /><i /></div>
      <Nebula mode={modeOf(build.status)} burst={writes.length} burstLabel={lastWrite} seed={hashSeed(build.id) % 997} density={compact ? 0.6 : 1} />
      <div className="cy-stage-top">
        <span className="cy-stage-k">{running ? <><i className="cy-pulse" /> Cyrus is thinking</> : build.status === "succeeded" ? "Built" : "Stopped"}</span>
        <h2 className="cy-stage-h">{head}</h2>
        {!compact && running && stream.length > 0 && (
          <ol className="cy-thoughts">
            {stream.map((e, i) => (
              <li key={`${e.at}-${i}`} style={{ opacity: 0.35 + (0.65 * (i + 1)) / stream.length }}>
                <span className="t">+{Math.max(0, Math.round((new Date(e.at).getTime() - new Date(startedAt || e.at).getTime()) / 1000))}s</span>
                <span className="m">{e.message}</span>
              </li>
            ))}
          </ol>
        )}
      </div>
      <div className="cy-stage-time" suppressHydrationWarning>
        <CyIcon name="clock" size={12} /> {running ? (startedAt ? dur(elapsed) : "—") : dur(build.durationMs)}
      </div>
      <ol className="cy-track" aria-label="Stages">
        {CYRUS_STAGES.map((s) => {
          const si = ORDER.indexOf(s.key);
          let cls = "pending";
          if (build.status === "failed") cls = seen.has(s.key) ? "done" : "pending";
          if (s.key === build.status) cls = "now";
          else if (build.status !== "failed" && si < idx) cls = s.key === "repairing" && !seen.has("repairing") ? "skip" : "done";
          return (
            <li key={s.key} className={`cy-tr ${cls}`}>
              <span className="cy-tr-node">{cls === "done" ? <CyIcon name="check" size={10} strokeWidth={2.6} /> : null}</span>
              <span className="cy-tr-l">{s.label}</span>
              <span className="cy-tr-s">{cls === "skip" ? "Not needed" : s.key === "repairing" && repairs ? `Fix ${repairs} of 3` : s.sub}</span>
            </li>
          );
        })}
      </ol>
    </section>
  );
}

