"use client";

import { useState } from "react";
import type { ModBuildView } from "@/lib/modbuilder/types";
import { viewMeta } from "@/lib/cyrus/projects";
import { CyIcon } from "./icons";

/** "Explain this mod": everything the build reported, in plain English. */
export function Overview({ b }: { b: ModBuildView }) {
  const r = b.result;
  const s = r?.summary;
  return (
    <div className="cy-ov">
      <div className="cy-ov-main">
        <section className="cy-card cy-explain">
          <span className="cy-k"><CyIcon name="sparkle" size={12} /> In plain English</span>
          <h3>{s?.tagline || `${b.pluginName} is built`}</h3>
          {s?.text && <p className="cy-lead">{s.text}</p>}
          {s?.changes && b.changeRequest && (
            <p className="cy-changed"><b>What changed in this version.</b> {s.changes}</p>
          )}
        </section>

        {!!s?.howToUse?.length && (
          <section className="cy-card">
            <h4>How to use it</h4>
            <ol className="cy-steps">
              {s.howToUse.map((h, i) => <li key={i}><span className="cy-step-n">{i + 1}</span><span>{h}</span></li>)}
            </ol>
          </section>
        )}

        {!!r?.commands?.length && (
          <section className="cy-card">
            <h4>Commands <span className="cy-count">{r.commands.length}</span></h4>
            <div className="cy-rows">
              {r.commands.map((c, i) => (
                <div key={i} className="cy-row">
                  <span className="cy-row-k"><code className="cy-cmd">{c.usage}</code></span>
                  <span className="cy-row-v">{c.description}</span>
                  <span className={`cy-who ${/every/i.test(c.whoCanUse) || (!c.whoCanUse && !c.permission) ? "all" : ""}`}>{c.whoCanUse || (c.permission ? "With permission" : "Everyone")}</span>
                </div>
              ))}
            </div>
          </section>
        )}

        {!!r?.config?.length && (
          <section className="cy-card">
            <h4>Settings you can change</h4>
            <p className="cy-sub">In <code className="cy-cmd">plugins/{b.pluginName}/config.yml</code> on your server.</p>
            <div className="cy-rows">
              {r.config.map((c, i) => (
                <div key={i} className="cy-row">
                  <span className="cy-row-k"><b className="cy-anywhere">{c.key}</b></span>
                  <span className="cy-row-v">{c.description}</span>
                  <span className="cy-row-d cy-anywhere">{c.default ? `Default: ${c.default}` : ""}</span>
                </div>
              ))}
            </div>
          </section>
        )}
        <Request b={b} />
      </div>

      <aside className="cy-ov-side">
        <Safety b={b} />
        {!!r?.permissions?.length && (
          <section className="cy-card">
            <h4>Who can do what</h4>
            <p className="cy-sub">Works with LuckPerms or any permissions plugin.</p>
            {r.permissions.map((p, i) => (
              <div key={i} className="cy-perm">
                <span className="flex items-center justify-between gap-2">
                  <b className="cy-anywhere">{p.node}</b>
                  <span className={`cy-who ${p.default === "true" ? "all" : ""}`}>{p.default === "true" ? "Everyone" : p.default === "false" ? "Nobody by default" : "Operators"}</span>
                </span>
                <span className="cy-sub">{p.description}</span>
              </div>
            ))}
          </section>
        )}
        {(!!s?.limitations?.length || !!r?.warnings?.length) && (
          <section className="cy-card">
            <h4><CyIcon name="warn" size={13} className="cy-amber" /> Good to know</h4>
            <ul className="cy-bullets">
              {(s?.limitations ?? []).map((l, i) => <li key={`l${i}`}>{l}</li>)}
              {(r?.warnings ?? []).slice(0, 6).map((w, i) => <li key={`w${i}`}>{w}</li>)}
            </ul>
          </section>
        )}
        <section className="cy-card cy-soon">
          <span className="cy-badge"><CyIcon name="sparkle" size={10} /> Built with Cyrus</span>
          <h4>Coming to Cyrus mods</h4>
          <ul className="cy-soon-l">
            <li><CyIcon name="server" size={13} /> Your server&apos;s Mods tab, with an on/off switch</li>
            <li><CyIcon name="users" size={13} /> A Cyrus Mods community in NxLabs</li>
            <li><CyIcon name="globe" size={13} /> Open source, so anyone can learn from them</li>
          </ul>
          <button type="button" className="cy-btn ghost" disabled>Publish to NxLabs · soon</button>
        </section>
      </aside>
    </div>
  );
}

function Request({ b }: { b: ModBuildView }) {
  const atts = viewMeta(b).attachments ?? [];
  return (
    <section className="cy-card">
      <h4>{b.changeRequest ? "The change you asked for" : "What you asked for"}</h4>
      <blockquote className="cy-quote">{b.changeRequest || b.prompt}</blockquote>
      {b.changeRequest && <details className="cy-details"><summary>Original description</summary><p>{b.prompt}</p></details>}
      {atts.length > 0 && (
        <div className="cy-refs">
          {atts.map((a) => (
            <a key={a.n} href={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} target="_blank" rel="noreferrer" className="cy-ref" title={a.name}>
              {/* eslint-disable-next-line @next/next/no-img-element */}
              <img src={`/api/mod-builder/builds/${b.id}/attachments/${a.n}`} alt={a.name} loading="lazy" />
            </a>
          ))}
          <span className="cy-sub">Reference images are kept with this version. Cyrus doesn&apos;t read images yet.</span>
        </div>
      )}
    </section>
  );
}

function Safety({ b }: { b: ModBuildView }) {
  const sf = b.result?.safety;
  const warns = (sf?.findings ?? []).filter((f) => f.severity === "warn");
  const checks: [string, string][] = [
    ["No internet access", "It can't send your data anywhere."],
    ["Can't run programs", "Nothing outside the game gets started."],
    ["Only its own folder", `Reads and writes only plugins/${b.pluginName || ""}.`],
    ["No hidden admin access", "No secret players with special powers."],
  ];
  return (
    <section className="cy-card cy-safety">
      <div className="flex items-center gap-2">
        <span className="cy-shield"><CyIcon name="shield" size={16} /></span>
