"use client";

import { useMemo, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import { CYRUS_STATUS_LABEL, cyrusModel } from "@/lib/cyrus/models";
import { viewMeta, type CyrusProject } from "@/lib/cyrus/projects";
import { CyIcon } from "./icons";
import { DiffView } from "./DiffView";
import { ago, dur } from "./util";

type Lane = { id: string; x: number; lane: number; parent: string | null; b: ModBuildView };

/** Lay versions out as a constellation: time left to right, a new lane for every branch. */
export function laneLayout(builds: ModBuildView[]): Lane[] {
  const out: Lane[] = [];
  const tipOfLane: (string | null)[] = [];
  const laneOf = new Map<string, number>();
  builds.forEach((b, i) => {
    const parent = b.baseBuildId && builds.some((x) => x.id === b.baseBuildId) ? b.baseBuildId : i > 0 ? null : null;
    let lane = 0;
    if (parent) {
      const pl = laneOf.get(parent) ?? 0;
      if (tipOfLane[pl] === parent) lane = pl;
      else { lane = tipOfLane.findIndex((t, k) => k > pl && t === null); if (lane < 0) lane = tipOfLane.length; }
    } else if (i > 0) {
      // A retry of the root (no base): its own lane.
      lane = tipOfLane.length;
    }
    tipOfLane[lane] = b.id;
    laneOf.set(b.id, lane);
    out.push({ id: b.id, x: i, lane, parent, b });
  });
  return out;
}

export function Versions({ project, viewing, onOpen, onRestore, onBranch }: {
  project: CyrusProject; viewing: string; onOpen: (id: string) => void; onRestore: (id: string) => Promise<void>; onBranch: (id: string) => void;
}) {
  const builds = project.builds;
  const ok = builds.filter((b) => b.status === "succeeded");
  const [cmp, setCmp] = useState<{ a: string; b: string } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  const vn = (id: string) => builds.findIndex((b) => b.id === id) + 1;
  const headId = project.head?.id ?? null;

  const startCompare = (id: string) => {
    const other = id === headId ? ok.filter((b) => b.id !== id).slice(-1)[0]?.id : headId;
    if (!other) return;
    const [a, b] = vn(id) < vn(other) ? [id, other] : [other, id];
    setCmp({ a, b });
    requestAnimationFrame(() => document.getElementById("cy-compare")?.scrollIntoView({ behavior: "smooth", block: "start" }));
  };

  return (
    <div className="cy-versions">
      <Constellation project={project} viewing={viewing} onOpen={onOpen} />
      <ol className="cy-vlist">
        {[...builds].reverse().map((b) => {
          const n = vn(b.id);
          const m = viewMeta(b).model;
          const isHead = b.id === headId;
          const run = !isTerminal(b.status);
          return (
            <li key={b.id} className={`cy-v ${b.id === viewing ? "on" : ""} st-${b.status}`}>
              <button type="button" className="cy-v-main" onClick={() => onOpen(b.id)}>
                <span className={`cy-v-n ${isHead ? "head" : ""}`}>v{n}</span>
                <span className="flex min-w-0 flex-1 flex-col gap-0.5">
                  <span className="cy-v-t">{b.changeRequest || (n === 1 ? "First build" : "Rebuilt from the description")}</span>
                  <span className="cy-v-s">
                    <span className={`cy-dot st-${b.status}`} />{CYRUS_STATUS_LABEL[b.status] ?? b.status}
                    {m && <> · {cyrusModel(m).name}</>}
                    {b.version && b.status === "succeeded" && <> · plugin {b.version}</>}
                    {b.finishedAt && <> · {dur(b.durationMs)}</>}
                    <> · <span suppressHydrationWarning>{ago(b.createdAt)}</span></>
                    {b.baseBuildId && vn(b.baseBuildId) !== n - 1 && vn(b.baseBuildId) > 0 && <> · from v{vn(b.baseBuildId)}</>}
                  </span>
                </span>
                {isHead && <span className="cy-tag cur">Current</span>}
                {run && <i className="cy-spin" />}
              </button>
              {b.status === "succeeded" && (
                <span className="cy-v-act">
                  {ok.length > 1 && <button type="button" className="cy-ib" title="Compare" aria-label={`Compare v${n}`} onClick={() => startCompare(b.id)}><CyIcon name="compare" size={14} /></button>}
                  {!isHead && (
                    <button type="button" className="cy-ib" title="Make this the current version" aria-label={`Restore v${n}`} disabled={busy === b.id}
                            onClick={async () => { setBusy(b.id); await onRestore(b.id); setBusy(null); }}>
                      {busy === b.id ? <i className="cy-spin" /> : <CyIcon name="restore" size={14} />}
                    </button>
                  )}
                  <button type="button" className="cy-ib" title="Ask for a change based on this version" aria-label={`Branch from v${n}`} onClick={() => onBranch(b.id)}><CyIcon name="branch" size={14} /></button>
                </span>
              )}
            </li>
          );
        })}
      </ol>

      <section id="cy-compare" className="cy-card cy-cmp">
        <div className="cy-cmp-h">
          <h4 className="!m-0"><CyIcon name="compare" size={14} /> Compare versions</h4>
          {ok.length < 2 ? <span className="cy-sub">Build a second version to compare code side by side.</span> : (
            <span className="cy-cmp-pick">
              <select className="cy-sel" value={cmp?.a ?? ""} onChange={(e) => setCmp((c) => ({ a: e.target.value, b: c?.b ?? headId ?? ok[ok.length - 1].id }))} aria-label="From version">
                <option value="" disabled>From…</option>
                {ok.map((b) => <option key={b.id} value={b.id}>v{vn(b.id)}{b.id === headId ? " (current)" : ""}</option>)}
              </select>
              <CyIcon name="chevr" size={14} />
              <select className="cy-sel" value={cmp?.b ?? ""} onChange={(e) => setCmp((c) => ({ a: c?.a ?? ok[0].id, b: e.target.value }))} aria-label="To version">
                <option value="" disabled>To…</option>
                {ok.map((b) => <option key={b.id} value={b.id}>v{vn(b.id)}{b.id === headId ? " (current)" : ""}</option>)}
              </select>
              {!cmp && <button type="button" className="cy-btn sm" onClick={() => setCmp({ a: ok[ok.length - 2].id, b: ok[ok.length - 1].id })}>Latest two</button>}
            </span>
          )}
        </div>
        {cmp && cmp.a && cmp.b && cmp.a !== cmp.b && (
          <DiffView a={builds.find((b) => b.id === cmp.a)!} b={builds.find((b) => b.id === cmp.b)!} labelA={`v${vn(cmp.a)}`} labelB={`v${vn(cmp.b)}`} />
        )}
        {cmp && cmp.a === cmp.b && <p className="cy-sub">Pick two different versions.</p>}
      </section>
    </div>
  );
}

function Constellation({ project, viewing, onOpen }: { project: CyrusProject; viewing: string; onOpen: (id: string) => void }) {
  const lanes = useMemo(() => laneLayout(project.builds), [project.builds]);
  const nLanes = Math.max(1, ...lanes.map((l) => l.lane + 1));
  const step = 76, padX = 34, laneH = 44, padY = 30;
  const W = Math.max(320, padX * 2 + (lanes.length - 1) * step);
  const H = padY * 2 + (nLanes - 1) * laneH;
  const pos = (l: Lane) => ({ x: padX + l.x * step, y: padY + l.lane * laneH });
  const by = new Map(lanes.map((l) => [l.id, l]));
  const headId = project.head?.id;
  return (
    <div className="cy-constel" role="list" aria-label="Version map">
      <svg viewBox={`0 0 ${W} ${H}`} width={W} height={H} style={{ minWidth: W }}>
        {lanes.map((l, i) => {
          const p = l.parent ? by.get(l.parent) : i > 0 ? lanes[0] : null;
          if (!p) return null;
          const a = pos(p), b = pos(l);
          const d = a.y === b.y ? `M${a.x},${a.y} L${b.x},${b.y}` : `M${a.x},${a.y} C${a.x + step * 0.6},${a.y} ${b.x - step * 0.6},${b.y} ${b.x},${b.y}`;
          return <path key={l.id} d={d} className={`cy-edge ${l.b.status === "failed" ? "bad" : ""} ${!l.parent ? "dash" : ""}`} />;
        })}
        {lanes.map((l, i) => {
          const { x, y } = pos(l);
          const st = l.b.status;
          const run = !isTerminal(st);
          return (
            <g key={l.id} className={`cy-vnode st-${st} ${l.id === viewing ? "on" : ""} ${l.id === headId ? "head" : ""} ${run ? "run" : ""}`}
               role="listitem" tabIndex={0} aria-label={`Version ${i + 1}, ${CYRUS_STATUS_LABEL[st] ?? st}`}
               onClick={() => onOpen(l.id)} onKeyDown={(e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); onOpen(l.id); } }}>
              <circle cx={x} cy={y} r="15" className="halo" />
              <circle cx={x} cy={y} r={l.id === headId ? 8 : 6.5} className="core" />
              {l.id === headId && <circle cx={x} cy={y} r="11.5" className="ring" />}
              <text x={x} y={y + 27} textAnchor="middle" className="lbl">v{i + 1}</text>
            </g>
          );
        })}
      </svg>
    </div>
  );
}

