                <span className={`cy-srv-dot ${s.status === "RUNNING" ? "up" : ""}`} />
                <span className="flex min-w-0 flex-1 flex-col">
                  <b className="truncate">{s.name}</b>
                  <span className="cy-sub">{s.compatible ? `${cap(s.variant)} · ${s.status === "RUNNING" ? "online" : "stopped"}` : s.reason}</span>
                </span>
                {sel === s.id && <CyIcon name="check" size={15} />}
              </label>
            ))}
          </div>
          {chosen?.status === "RUNNING" && (
            <label className="cy-checkrow">
              <input type="checkbox" checked={restart} onChange={(e) => setRestart(e.target.checked)} />
              <span><b>Restart the server now</b> so the mod loads. Players get a short warning first.</span>
            </label>
          )}
          <p className="cy-sub">If an older version of {build.pluginName} is already there, we back it up before replacing it.</p>
          {err && <p role="alert" className="cy-err">{err}</p>}
          <div className="flex justify-end gap-2">
            <button type="button" className="cy-btn" onClick={onClose}>Cancel</button>
            <button type="button" className="cy-btn primary" disabled={!sel || busy} onClick={go}>
              {busy ? <i className="cy-spin" /> : <CyIcon name="server" size={14} />} {busy ? "Installing…" : "Install"}
            </button>
          </div>
        </>
      )}
    </Modal>
  );
}

const cap = (s: string | null) => (s ? s[0].toUpperCase() + s.slice(1) : "");

export const SHORTCUTS: [string, string][] = [
  ["N", "New mod"],
  ["P", "Switch project"],
  ["[  ]", "Previous / next project"],
  ["/", "Focus the prompt"],
  ["V", "Voice typing on / off"],
  ["⌘ ↵", "Build (Ctrl + Enter on Windows)"],
  ["1 – 4", "Overview, Code, Versions, Notes"],
  ["F", "Favourite this project"],
  ["?", "This list"],
  ["Esc", "Close"],
];

export function ShortcutsModal({ onClose }: { onClose: () => void }) {
  return (
    <Modal title="Keyboard shortcuts" sub="Single keys work when you're not typing in a box." onClose={onClose}>
      <div className="cy-keys">
        {SHORTCUTS.map(([k, d]) => (
          <div key={k} className="cy-key-row"><span className="cy-keycap">{k}</span><span>{d}</span></div>
        ))}
      </div>
    </Modal>
  );
}

export function ProjectPalette({ projects, onPick, onNew, onClose }: { projects: CyrusProject[]; onPick: (p: CyrusProject) => void; onNew: () => void; onClose: () => void }) {
  const [q, setQ] = useState("");
  const [i, setI] = useState(0);
  const inp = useRef<HTMLInputElement>(null);
  useEffect(() => { inp.current?.focus(); }, []);
  const list = useMemo(() => {
    const s = q.trim().toLowerCase();
    return s ? projects.filter((p) => p.title.toLowerCase().includes(s) || p.latest.prompt.toLowerCase().includes(s)) : projects;
  }, [q, projects]);
  useEffect(() => setI(0), [q]);
  return (
    <Modal title="Switch project" onClose={onClose}>
      <div className="cy-search">
        <CyIcon name="search" size={15} />
        <input ref={inp} value={q} onChange={(e) => setQ(e.target.value)} placeholder="Find a mod…" aria-label="Find a project"
               onKeyDown={(e) => {
                 if (e.key === "ArrowDown") { e.preventDefault(); setI((x) => Math.min(list.length - 1, x + 1)); }
                 if (e.key === "ArrowUp") { e.preventDefault(); setI((x) => Math.max(0, x - 1)); }
                 if (e.key === "Enter") { e.preventDefault(); if (list[i]) onPick(list[i]); else onNew(); }
               }} />
      </div>
      <div className="cy-pal" role="listbox">
        {list.slice(0, 40).map((p, k) => (
          <button key={p.rootId} type="button" role="option" aria-selected={k === i} className={`cy-pal-i ${k === i ? "on" : ""}`} onMouseEnter={() => setI(k)} onClick={() => onPick(p)}>
            <Glyph id={p.rootId} size={26} state={p.running ? "running" : p.head ? "ok" : "bad"} />
            <span className="flex min-w-0 flex-1 flex-col text-left">
              <b className="truncate">{p.title}</b>
              <span className="cy-sub truncate">v{p.builds.length} · {CYRUS_STATUS_LABEL[(p.running ?? p.latest).status]}</span>
            </span>
            {p.meta.favourite && <CyIcon name="star" size={13} fill className="cy-amber" />}
          </button>
        ))}
        {list.length === 0 && <p className="cy-sub px-2 py-3">No project matches. Press Enter to start a new mod.</p>}
      </div>
    </Modal>
  );
}

