"use client";

import { useEffect, useRef, useState } from "react";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { CYRUS_DEFAULT_MODEL, CYRUS_STATUS_LABEL, cyrusModel } from "@/lib/cyrus/models";
import { viewMeta, versionNumber, type CyrusProject } from "@/lib/cyrus/projects";
import { CYRUS_NOTES_MAX, type CyrusMeta } from "@/lib/cyrus/meta";
import { Composer, type ComposerHandle, type ComposerSubmit } from "./Composer";
import { CodePane } from "./CodePane";
import { Failure, Overview } from "./Overview";
import { Stage, PROGRESS } from "./Stage";
import { Versions } from "./Versions";
import { InstallModal } from "./Modals";
import { CyIcon } from "./icons";
import { Glyph } from "./Glyph";
import { ago, bytes, dur, isTypingTarget } from "./util";

export type Tab = "overview" | "code" | "versions" | "notes";

export function Project({ project, viewing, servers, inflight, onOpen, onCreate, onPatch, onDuplicate, onRefresh, composerRef, onNewMod }: {
  project: CyrusProject;
  viewing: ModBuildView;
  servers: MbServer[];
  inflight: number;
  onOpen: (id: string) => void;
  onCreate: (body: Record<string, unknown>) => Promise<string | null>;
  onPatch: (rootId: string, patch: Partial<CyrusMeta> & { title?: string | null; headBuildId?: string | null }) => Promise<string | null>;
  onDuplicate: (p: CyrusProject) => Promise<string | null>;
  onRefresh: () => void;
  composerRef: React.RefObject<ComposerHandle | null>;
  onNewMod: () => void;
}) {
  const b = viewing;
  const running = !isTerminal(b.status);
  const n = versionNumber(project, b.id);
  const isHead = project.head?.id === b.id;
  const [tab, setTab] = useState<Tab>("overview");
  const [modal, setModal] = useState<null | "install">(null);
  const [menu, setMenu] = useState(false);
  const [rename, setRename] = useState(false);
  const [branchFrom, setBranchFrom] = useState<string | null>(null);
  const meta = project.meta;
  const bm = viewMeta(b);

  // A build that just finished while being watched gets the reveal + the Code tab nudge.
  const wasRunning = useRef(running);
  const [justDone, setJustDone] = useState<string | null>(null);
  useEffect(() => {
    if (wasRunning.current && !running) { setJustDone(b.id); if (b.status === "succeeded") setTab("overview"); }
    wasRunning.current = running;
  }, [running, b.id, b.status]);
  useEffect(() => { setBranchFrom(null); setMenu(false); }, [b.id]);

  // 1-4 switch tabs, F favourites.
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (isTypingTarget(e.target) || e.metaKey || e.ctrlKey || e.altKey || document.querySelector(".cy-modal-back")) return;
      const t = ({ "1": "overview", "2": "code", "3": "versions", "4": "notes" } as Record<string, Tab>)[e.key];
      if (t) { setTab(t); e.preventDefault(); }
      if (e.key === "f" || e.key === "F") { onPatch(project.rootId, { favourite: !meta.favourite }); e.preventDefault(); }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [project.rootId, meta.favourite, onPatch]);

  const base = branchFrom ? project.builds.find((x) => x.id === branchFrom) ?? null : b.status === "succeeded" ? b : project.head;
  const baseN = base ? versionNumber(project, base.id) : 0;
  const disabledReason = project.running ? `Cyrus is building v${versionNumber(project, project.running.id)}. Ask for the next change when it's done.`
    : !base ? "This mod hasn't built yet. Try again first, then ask for changes."
    : inflight >= 2 ? "Two builds are running. Cyrus builds two at a time in the preview." : null;

  const submitChange = async (s: ComposerSubmit) => {
    if (!base) return "Nothing to change yet.";
    return onCreate({ baseBuildId: base.id, changeRequest: s.text, model: s.model, attachmentIds: s.attachmentIds });
  };
  const retry = async () => onCreate(b.baseBuildId
    ? { baseBuildId: b.baseBuildId, changeRequest: b.changeRequest, model: bm.model }
    : { prompt: b.prompt, mcVersion: b.mcVersion, model: bm.model });
  const editRetry = () => {
    if (b.baseBuildId) { setBranchFrom(b.baseBuildId); composerRef.current?.setText(b.changeRequest || "", bm.model); }
    else composerRef.current?.setText(b.prompt, bm.model);
  };

  const ok = b.status === "succeeded";
  const files = b.result?.files ?? [];
  const parent = b.baseBuildId ? project.builds.find((x) => x.id === b.baseBuildId) ?? null : null;
  const model = cyrusModel(bm.model ?? CYRUS_DEFAULT_MODEL);

  return (
    <div className="cy-project">
      <header className="cy-ph">
        <Glyph id={project.rootId} size={52} state={running ? "running" : ok ? "ok" : "bad"} progress={PROGRESS[b.status]} />
        <div className="flex min-w-0 flex-1 flex-col gap-1.5">
          <div className="cy-ph-row">
            {rename ? (
              <form className="cy-rename" onSubmit={async (e) => { e.preventDefault(); const v = String(new FormData(e.currentTarget).get("t") || ""); await onPatch(project.rootId, { title: v || null }); setRename(false); }}>
                <input name="t" autoFocus defaultValue={project.title} maxLength={60} aria-label="Project name" onBlur={(e) => e.currentTarget.form?.requestSubmit()} onKeyDown={(e) => { if (e.key === "Escape") setRename(false); }} />
              </form>
            ) : (
              <h1 className="cy-ph-t" onDoubleClick={() => setRename(true)} title="Double-click to rename">{project.title}</h1>
            )}
            <button type="button" className={`cy-ib star ${meta.favourite ? "on" : ""}`} aria-pressed={!!meta.favourite} aria-label={meta.favourite ? "Remove from favourites" : "Add to favourites"} title="Favourite (F)"
                    onClick={() => onPatch(project.rootId, { favourite: !meta.favourite })}>
              <CyIcon name="star" size={16} fill={!!meta.favourite} />
            </button>
            {ok && <span className="cy-badge" title="Built with Cyrus"><CyIcon name="sparkle" size={10} /> Cyrus</span>}
          </div>
          <div className="cy-ph-meta">
            <span className={`cy-pill st-${b.status}`}><i />{CYRUS_STATUS_LABEL[b.status]}</span>
            <span className="cy-chip">v{n}{project.builds.length > 1 ? ` of ${project.builds.length}` : ""}</span>
            <span className="cy-chip">Minecraft · Paper {b.mcVersion}</span>
            <span className="cy-chip"><span className="cy-model-dot" style={{ background: model.hue }} />{model.name}</span>
            {ok && b.version && <span className="cy-chip dim">plugin {b.version}</span>}
            {ok && <span className="cy-meta-t">built in {dur(b.durationMs)}{b.attempts > 1 ? ` · fixed itself ${b.attempts - 1}×` : " · first try"}</span>}
            {!ok && <span className="cy-meta-t" suppressHydrationWarning>started {ago(b.createdAt)}</span>}
          </div>
        </div>
        <div className="cy-ph-act">
          {ok && (
            <>
              <a href={`/api/mod-builder/builds/${b.id}/jar`} className="cy-btn primary" download><CyIcon name="download" size={14} /> <span>Download</span></a>
              <button type="button" className="cy-btn" onClick={() => setModal("install")}><CyIcon name="server" size={14} /> <span>Install</span></button>
            </>
          )}
          {running && (
            <button type="button" className="cy-btn" onClick={async () => { await fetch(`/api/mod-builder/builds/${b.id}/cancel`, { method: "POST" }); onRefresh(); }}>
              <CyIcon name="stop" size={13} /> Cancel
            </button>
          )}
          <span className="relative">
            <button type="button" className="cy-ib lg" aria-label="More" aria-expanded={menu} onClick={() => setMenu((v) => !v)}><CyIcon name="more" size={18} strokeWidth={2.4} /></button>
            {menu && (
              <span className="cy-menu" role="menu" onMouseLeave={() => setMenu(false)}>
                <button type="button" role="menuitem" onClick={async () => { setMenu(false); await onDuplicate(project); }}><CyIcon name="copy" size={14} /> Duplicate as a new project</button>
                <button type="button" role="menuitem" onClick={() => { setMenu(false); setRename(true); }}><CyIcon name="pencil" size={14} /> Rename</button>
                {ok && <a role="menuitem" href={`/api/mod-builder/builds/${b.id}/source-zip`}><CyIcon name="download" size={14} /> Download source (.zip)</a>}
                <button type="button" role="menuitem" onClick={() => { setMenu(false); navigator.clipboard?.writeText(b.changeRequest || b.prompt); }}><CyIcon name="note" size={14} /> Copy the request</button>
                <button type="button" role="menuitem" onClick={() => { setMenu(false); onNewMod(); }}><CyIcon name="plus" size={14} /> New mod</button>
              </span>
            )}
          </span>
        </div>
      </header>

      {!isHead && ok && project.head && (
        <div className="cy-banner">
          <CyIcon name="layers" size={14} />
          <span>You&apos;re looking at <b>v{n}</b>. The current version is <b>v{versionNumber(project, project.head.id)}</b>.</span>
          <span className="ml-auto flex flex-wrap gap-1.5">
            <button type="button" className="cy-btn sm" onClick={() => onPatch(project.rootId, { headBuildId: b.id })}><CyIcon name="restore" size={13} /> Make v{n} current</button>
            <button type="button" className="cy-btn sm ghost" onClick={() => onOpen(project.head!.id)}>Go to current</button>
          </span>
        </div>
      )}

      {running && (
        <div className="cy-live-grid">
          <Stage build={b} />
          <CodePane build={b} base={parent} height={440} />
        </div>
      )}
      {!running && (b.status === "failed" || justDone === b.id) && <Stage build={b} compact />}
      {b.status === "failed" && <Failure b={b} onRetry={retry} onEdit={editRetry} />}

      {!running && (
        <>
          <div className="cy-tabs" role="tablist">
            {(["overview", "code", "versions", "notes"] as Tab[]).map((t, i) => (
              <button key={t} type="button" role="tab" aria-selected={tab === t} className={`cy-tab ${tab === t ? "on" : ""}`} onClick={() => setTab(t)}>
                {{ overview: ok ? "Overview" : "Request", code: "Code", versions: "Versions", notes: "Notes" }[t]}
                {t === "versions" && <span className="cy-tab-n">{project.builds.length}</span>}
                {t === "code" && files.length > 0 && <span className="cy-tab-n">{files.filter((f) => f.path.startsWith("src/")).length}</span>}
                <span className="cy-tab-k" aria-hidden="true">{i + 1}</span>
              </button>
            ))}
          </div>
          <div role="tabpanel">
            {tab === "overview" && (ok ? <Overview b={b} /> : <FailedRequest b={b} />)}
            {tab === "code" && (files.length ? (
              <section className="flex flex-col gap-3">
                <CodePane build={b} height={560} revealKey={justDone === b.id ? b.id : undefined} />
                <p className="cy-sub">Source is yours to keep. The .zip includes a Gradle project so a developer can rebuild it. {ok && b.jarName && <>{b.jarName} · {bytes(b.jarSize)}</>}</p>
              </section>
            ) : <p className="cy-empty-t">No source for this version.</p>)}
            {tab === "versions" && (
              <Versions project={project} viewing={b.id} onOpen={onOpen}
                        onRestore={async (id) => { await onPatch(project.rootId, { headBuildId: id }); }}
                        onBranch={(id) => { setBranchFrom(id); composerRef.current?.focus(); }} />
            )}
            {tab === "notes" && <Notes key={project.rootId} project={project} onPatch={onPatch} />}
          </div>
        </>
      )}

      <div className="cy-dock">
        {branchFrom && base && (
          <div className="cy-dock-note"><CyIcon name="branch" size={13} /> Branching from <b>v{baseN}</b> <button type="button" onClick={() => setBranchFrom(null)}>Use {b.status === "succeeded" ? `v${n}` : "current"} instead</button></div>
        )}
        <Composer ref={composerRef} kind="change" compact
                  placeholder={base ? `Ask Cyrus to change v${baseN}… e.g. “add a /reload command and make the messages purple”` : "Ask for a change once this mod builds"}
                  defaultModel={bm.model ?? project.head ? viewMeta(project.head ?? b).model ?? CYRUS_DEFAULT_MODEL : CYRUS_DEFAULT_MODEL}
                  lockVersion={b.mcVersion} disabledReason={disabledReason} submitLabel={base ? `Build v${project.builds.length + 1}` : "Build"} onSubmit={submitChange} />
      </div>

      {modal === "install" && <InstallModal build={b} servers={servers} onClose={() => setModal(null)} onDone={onRefresh} />}
    </div>
  );
}

function FailedRequest({ b }: { b: ModBuildView }) {
  return (
    <section className="cy-card">
      <h4>{b.changeRequest ? "The change you asked for" : "What you asked for"}</h4>
      <blockquote className="cy-quote">{b.changeRequest || b.prompt}</blockquote>
    </section>
  );
}

function Notes({ project, onPatch }: { project: CyrusProject; onPatch: (rootId: string, p: { notes: string }) => Promise<string | null> }) {
  const [v, setV] = useState(project.meta.notes ?? "");
  const [state, setState] = useState<"saved" | "dirty" | "saving" | "error">("saved");
  const t = useRef<number | undefined>(undefined);
  const save = async (text: string) => {
    setState("saving");
    const e = await onPatch(project.rootId, { notes: text });
    setState(e ? "error" : "saved");
  };
  return (
    <section className="cy-card cy-notes">
      <div className="flex items-center gap-2">
        <h4 className="!m-0"><CyIcon name="note" size={14} /> Project notes</h4>
        <span className={`cy-save ${state}`}>{state === "saving" ? "Saving…" : state === "dirty" ? "Unsaved" : state === "error" ? "Couldn't save" : "Saved"}</span>
      </div>
      <p className="cy-sub">Only you see these. Ideas for the next version, what players said, server setup reminders.</p>
      <textarea value={v} maxLength={CYRUS_NOTES_MAX} rows={10} placeholder="e.g. Players want the shop to sell elytra. Try a 7-day streak reward next."
                onChange={(e) => { setV(e.target.value); setState("dirty"); window.clearTimeout(t.current); const text = e.target.value; t.current = window.setTimeout(() => save(text), 800); }}
                onBlur={() => { if (state === "dirty") { window.clearTimeout(t.current); save(v); } }} />
      <span className="cy-fine">{v.length.toLocaleString("en-US")} / {CYRUS_NOTES_MAX.toLocaleString("en-US")}</span>
    </section>
  );
}

