"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { usePathname } from "next/navigation";
import { isTerminal, type ModBuildView } from "@/lib/modbuilder/types";
import type { MbServer } from "@/lib/modbuilder/install";
import { CYRUS_DEFAULT_MODEL, CYRUS_STATUS_LABEL, cyrusModel } from "@/lib/cyrus/models";
import { groupProjects, projectOf, viewMeta, versionNumber, type CyrusProject } from "@/lib/cyrus/projects";
import { CYRUS_TEMPLATES, CYRUS_TEMPLATE_CATS } from "@/lib/cyrus/templates";
import { estimate } from "@/lib/cyrus/estimate";
import type { CyrusMeta } from "@/lib/cyrus/meta";
import { Composer, type ComposerHandle, type ComposerSubmit } from "./Composer";
import { Nebula, type NebulaMode } from "./Nebula";
import { Project } from "./Project";
import { ProjectPalette, ShortcutsModal } from "./Modals";
import { CyIcon, CyrusMark } from "./icons";
import { Glyph } from "./Glyph";
import { PROGRESS } from "./Stage";
import { ago, isTypingTarget } from "./util";

const BASE = "/dashboard/cyrus";
type Toast = { id: string; text: string; buildId: string; ok: boolean };

export function CyrusApp({ initialBuilds, servers, online, firstName }: { initialBuilds: ModBuildView[]; servers: MbServer[]; online: boolean; firstName: string }) {
  const [builds, setBuilds] = useState<ModBuildView[]>(initialBuilds);
  const [netErr, setNetErr] = useState(false);
  const [toasts, setToasts] = useState<Toast[]>([]);
  const [modal, setModal] = useState<null | "palette" | "keys">(null);
  const [railQ, setRailQ] = useState("");
  const pathname = usePathname();
  const selectedId = pathname.startsWith(BASE + "/") ? decodeURIComponent(pathname.slice(BASE.length + 1).split("/")[0]) : null;
  const homeComposer = useRef<ComposerHandle>(null);
  const changeComposer = useRef<ComposerHandle>(null);

  const projects = useMemo(() => groupProjects(builds), [builds]);
  const project = projectOf(projects, selectedId);
  const viewing = project?.builds.find((b) => b.id === selectedId) ?? null;
  const inflight = builds.filter((b) => !isTerminal(b.status)).length;

  const go = useCallback((id: string | null) => {
    const url = id ? `${BASE}/${id}` : BASE;
    if (url !== window.location.pathname) window.history.pushState(null, "", url);
    window.scrollTo({ top: 0, behavior: "smooth" });
  }, []);
  const openProject = useCallback((p: CyrusProject) => go((p.running ?? p.head ?? p.latest).id), [go]);

  const upsert = useCallback((list: ModBuildView[]) => {
    setBuilds((cur) => {
      const m = new Map(cur.map((b) => [b.id, b]));
      for (const b of list) {
        const prev = m.get(b.id);
        if (prev && !isTerminal(prev.status) && isTerminal(b.status)) {
          setToasts((t) => [...t.filter((x) => x.buildId !== b.id), { id: b.id + b.status, buildId: b.id, ok: b.status === "succeeded", text: b.status === "succeeded" ? `${b.pluginName || "Your mod"} is ready` : `${b.pluginName || "A build"} didn't build` }]);
        }
        m.set(b.id, { ...prev, ...b });
      }
      return Array.from(m.values());
    });
  }, []);

  // Poll every in-flight build (each GET also syncs it from the build service).
  useEffect(() => {
    const ids = builds.filter((b) => !isTerminal(b.status)).map((b) => b.id);
    if (!ids.length) return;
    let stop = false;
    const t = setTimeout(async () => {
      const res = await Promise.all(ids.map((id) => fetch(`/api/mod-builder/builds/${id}`, { cache: "no-store" }).then((r) => (r.ok ? r.json() : null)).catch(() => null)));
      if (stop) return;
      upsert(res.filter(Boolean).map((j) => j.build as ModBuildView));
      setNetErr(res.some((r) => !r));
    }, document.visibilityState === "hidden" ? 9000 : 2500);
    return () => { stop = true; clearTimeout(t); };
  }, [builds, upsert]);

  const refreshAll = useCallback(async () => {
    const r = await fetch("/api/mod-builder/builds", { cache: "no-store" }).catch(() => null);
    if (r?.ok) { const j = await r.json(); upsert(j.builds as ModBuildView[]); }
  }, [upsert]);
  // Builds started in another tab show up here too.
  useEffect(() => { const t = setInterval(refreshAll, 30_000); return () => clearInterval(t); }, [refreshAll]);

  // Toasts fade after a while.
  useEffect(() => {
    if (!toasts.length) return;
    const t = setTimeout(() => setToasts((x) => x.slice(1)), 7000);
    return () => clearTimeout(t);
  }, [toasts]);
  useEffect(() => { if (selectedId) setToasts((t) => t.filter((x) => x.buildId !== selectedId)); }, [selectedId]);

  const create = useCallback(async (body: Record<string, unknown>): Promise<string | null> => {
    try {
      const r = await fetch("/api/mod-builder/builds", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) return j.error || "Cyrus couldn't start this build.";
      upsert([j.build]);
      go(j.build.id);
      return null;
    } catch { return "We couldn't reach Nxeon. Check your connection and try again."; }
  }, [go, upsert]);

  const patch = useCallback(async (rootId: string, p: Record<string, unknown>): Promise<string | null> => {
    // Optimistic: update the root build's meta locally first.
    setBuilds((cur) => cur.map((b) => (b.id === rootId ? { ...b, cyrus: { ...viewMeta(b), ...cleanPatch(p) } } : b)));
    try {
      const r = await fetch(`/api/mod-builder/projects/${rootId}`, { method: "PATCH", headers: { "Content-Type": "application/json" }, body: JSON.stringify(p) });
      const j = await r.json().catch(() => ({}));
      if (!r.ok) { refreshAll(); return j.error || "Couldn't save."; }
      setBuilds((cur) => cur.map((b) => (b.id === rootId ? { ...b, cyrus: j.meta } : b)));
      return null;
    } catch { return "Couldn't save."; }
  }, [refreshAll]);

  const duplicate = useCallback(async (p: CyrusProject) => {
    const src = p.head ?? p.latest;
    return create({ prompt: (p.builds[0] ?? src).prompt, mcVersion: src.mcVersion, model: viewMeta(src).model ?? CYRUS_DEFAULT_MODEL });
  }, [create]);

  const newMod = useCallback(() => { go(null); setTimeout(() => homeComposer.current?.focus(), 60); }, [go]);

  // Global shortcuts.
  useEffect(() => {
    const k = (e: KeyboardEvent) => {
      if (e.key === "Escape" && modal) { setModal(null); return; }
      if (isTypingTarget(e.target) || e.metaKey || e.ctrlKey || e.altKey || modal) return;
      const comp = selectedId ? changeComposer.current : homeComposer.current;
      const idx = project ? projects.findIndex((p) => p.rootId === project.rootId) : -1;
      switch (e.key) {
        case "n": case "N": e.preventDefault(); newMod(); break;
        case "p": case "P": e.preventDefault(); setModal("palette"); break;
        case "?": e.preventDefault(); setModal("keys"); break;
        case "/": e.preventDefault(); comp?.focus(); break;
        case "v": case "V": e.preventDefault(); comp?.toggleVoice(); break;
        case "[": if (projects.length) { e.preventDefault(); openProject(projects[(idx - 1 + projects.length) % projects.length]); } break;
        case "]": if (projects.length) { e.preventDefault(); openProject(projects[(idx + 1) % projects.length]); } break;
      }
    };
    window.addEventListener("keydown", k);
    return () => window.removeEventListener("keydown", k);
  }, [modal, selectedId, project, projects, newMod, openProject]);

  const running = projects.filter((p) => p.running);
  const railList = railQ.trim() ? projects.filter((p) => p.title.toLowerCase().includes(railQ.trim().toLowerCase())) : projects;

  return (
    <div className="cy-root">
      <div className="cy-frame">
        <header className="cy-top">
          <button type="button" className="cy-brand" onClick={newMod} aria-label="Cyrus home">
            <CyrusMark size={30} />
            <span className="cy-word">Cyrus</span>
          </button>
          <span className="cy-preview">Preview</span>
          <span className={`cy-online ${online ? "up" : "down"}`} title={online ? "The builder is online" : "The builder is offline"}><i />{online ? "Builder online" : "Builder offline"}</span>
          {netErr && <span className="cy-online down"><i />Reconnecting…</span>}
          <span className="ml-auto flex items-center gap-1.5">
            {running.length > 0 && <span className="cy-running" title="Builds in progress"><i className="cy-pulse" />{running.length} weaving</span>}
            <button type="button" className="cy-topbtn" onClick={() => setModal("palette")} title="Switch project (P)"><CyIcon name="layers" size={15} /><span>Projects</span><kbd>P</kbd></button>
            <button type="button" className="cy-topbtn icon" onClick={() => setModal("keys")} title="Keyboard shortcuts (?)" aria-label="Keyboard shortcuts"><CyIcon name="keyboard" size={16} /></button>
          </span>
        </header>

        {/* phones: a horizontal project switcher replaces the rail */}
        <div className="cy-mswitch">
          <button type="button" className={`cy-mchip new ${!selectedId ? "on" : ""}`} onClick={newMod}><CyIcon name="plus" size={13} /> New</button>
          {projects.slice(0, 12).map((p) => (
            <button key={p.rootId} type="button" className={`cy-mchip ${project?.rootId === p.rootId ? "on" : ""}`} onClick={() => openProject(p)}>
              <Glyph id={p.rootId} size={20} state={p.running ? "running" : p.head ? "ok" : "bad"} progress={p.running ? PROGRESS[p.running.status] : undefined} />
              <span className="truncate">{p.title}</span>
            </button>
          ))}
        </div>

        <div className="cy-body">
          <aside className="cy-rail" aria-label="Projects">
            <button type="button" className={`cy-new ${!selectedId ? "on" : ""}`} onClick={newMod}>
              <CyIcon name="plus" size={15} strokeWidth={2} /> New mod <kbd>N</kbd>
            </button>
            {projects.length > 5 && (
              <label className="cy-rail-q"><CyIcon name="search" size={13} /><input value={railQ} onChange={(e) => setRailQ(e.target.value)} placeholder="Filter projects" aria-label="Filter projects" /></label>
            )}
            {projects.length === 0 && <p className="cy-rail-empty">Your mods appear here. Several can build at once.</p>}
            <RailGroup title="Weaving now" list={railList.filter((p) => p.running)} current={project?.rootId} onPick={openProject} />
            <RailGroup title="Favourites" list={railList.filter((p) => !p.running && p.meta.favourite)} current={project?.rootId} onPick={openProject} />
            <RailGroup title={running.length || projects.some((p) => p.meta.favourite) ? "All projects" : "Projects"} list={railList.filter((p) => !p.running && !p.meta.favourite)} current={project?.rootId} onPick={openProject} />
          </aside>

          <main className="cy-main">
            {selectedId && project && viewing ? (
              <Project key={project.rootId} project={project} viewing={viewing} servers={servers} inflight={inflight} onOpen={go} onCreate={create}
                       onPatch={patch} onDuplicate={duplicate} onRefresh={refreshAll} composerRef={changeComposer} onNewMod={newMod} />
            ) : selectedId ? (
              <div className="cy-empty"><CyrusMark size={40} /><p className="cy-empty-t">That build isn&apos;t here.</p><button type="button" className="cy-btn" onClick={newMod}>Back to Cyrus</button></div>
            ) : (
              <Home firstName={firstName} projects={projects} inflight={inflight} online={online} onCreate={create} onOpen={openProject} composerRef={homeComposer} />
            )}
          </main>
        </div>
      </div>

      <div className="cy-toasts" aria-live="polite">
        {toasts.map((t) => (
          <button key={t.id} type="button" className={`cy-toast ${t.ok ? "ok" : "bad"}`} onClick={() => { go(t.buildId); setToasts((x) => x.filter((y) => y.id !== t.id)); }}>
            <span className="cy-toast-orb"><CyIcon name={t.ok ? "check" : "warn"} size={13} strokeWidth={2.2} /></span>
            <span>{t.text}</span><span className="cy-toast-go">Open <CyIcon name="chevr" size={12} /></span>
          </button>
        ))}
      </div>

      {modal === "palette" && <ProjectPalette projects={projects} onClose={() => setModal(null)} onPick={(p) => { setModal(null); openProject(p); }} onNew={() => { setModal(null); newMod(); }} />}
      {modal === "keys" && <ShortcutsModal onClose={() => setModal(null)} />}
    </div>
  );
}

function cleanPatch(p: Record<string, unknown>): Partial<CyrusMeta> {
  const o: Record<string, unknown> = { ...p };
  for (const k of Object.keys(o)) if (o[k] === null) delete o[k];
  return o as Partial<CyrusMeta>;
}

function RailGroup({ title, list, current, onPick }: { title: string; list: CyrusProject[]; current?: string; onPick: (p: CyrusProject) => void }) {
  if (!list.length) return null;
  return (
    <div className="cy-rail-g">
      <div className="cy-rail-h">{title}<span>{list.length}</span></div>
      {list.map((p) => {
        const r = p.running;
        const b = r ?? p.head ?? p.latest;
        return (
          <button key={p.rootId} type="button" className={`cy-ri ${current === p.rootId ? "on" : ""} ${r ? "run" : ""}`} onClick={() => onPick(p)}>
            <Glyph id={p.rootId} size={34} state={r ? "running" : p.head ? "ok" : "bad"} progress={r ? PROGRESS[r.status] : undefined} />
            <span className="flex min-w-0 flex-1 flex-col">
              <span className="cy-ri-t">{p.title}{p.meta.favourite && <CyIcon name="star" size={10} fill className="cy-amber ml-1 inline" />}</span>
              <span className={`cy-ri-s st-${b.status}`}>
                {r ? <><i className="cy-dot st-run" />{CYRUS_STATUS_LABEL[r.status]} · v{versionNumber(p, r.id)}</>
                  : <>v{versionNumber(p, b.id)} · <span suppressHydrationWarning>{ago(p.updatedAt)}</span>{!p.head && <> · <span className="bad">{CYRUS_STATUS_LABEL.failed}</span></>}</>}
              </span>
            </span>
          </button>
        );
      })}
    </div>
  );
}

function Home({ firstName, projects, inflight, online, onCreate, onOpen, composerRef }: {
  firstName: string; projects: CyrusProject[]; inflight: number; online: boolean;
  onCreate: (b: Record<string, unknown>) => Promise<string | null>; onOpen: (p: CyrusProject) => void; composerRef: React.RefObject<ComposerHandle | null>;
}) {
  const [act, setAct] = useState<{ typing: boolean; listening: boolean; level: number }>({ typing: false, listening: false, level: 0 });
  const onActivity = useCallback((a: { typing: boolean; listening: boolean; level: number }) => {
    setAct((cur) => (cur.typing === a.typing && cur.listening === a.listening && Math.abs(cur.level - a.level) < 0.04 ? cur : a));
  }, []);
  const [cat, setCat] = useState<(typeof CYRUS_TEMPLATE_CATS)[number]>("All");
  const mode: NebulaMode = act.listening ? "listening" : act.typing ? "typing" : "idle";
  const submit = (s: ComposerSubmit) => onCreate({ prompt: s.text, mcVersion: s.mcVersion, model: s.model, attachmentIds: s.attachmentIds });
  const disabledReason = !online ? "The builder is offline right now. You can write your idea; building resumes shortly." : inflight >= 2 ? "Two builds are running. Cyrus builds two at a time in the preview." : null;
  const tpl = CYRUS_TEMPLATES.filter((t) => cat === "All" || t.cat === cat);
  const running = projects.filter((p) => p.running);

  return (
    <div className="cy-home">
      <section className={`cy-hero mode-${mode}`}>
        <div className="cy-aurora" aria-hidden="true"><i /><i /><i /></div>
        <Nebula mode={mode} energy={act.listening ? act.level : act.typing ? 0.5 : 0} seed={11} />
        <div className="cy-hero-in">
          <span className="cy-eyebrow"><CyrusMark size={16} /> AI mod studio</span>
          <h1 className="cy-h1">Speak a mod <span className="cy-grad">into existence.</span></h1>
          <p className="cy-hero-sub">Tell Cyrus what you want on your server, {firstName}. Watch it plan, write, compile, fix and safety-check a real plugin, then change it as often as you like.</p>
          <Composer ref={composerRef} kind="new" defaultModel={CYRUS_DEFAULT_MODEL} disabledReason={disabledReason} submitLabel="Build with Cyrus" onActivity={onActivity}
                    placeholder="Describe your mod… e.g. “A /shop menu where players spend coins they earn from killing mobs.” Paste a screenshot or press the mic to talk." />
          <ul className="cy-promise">
            <li><CyIcon name="code" size={13} /> Real Java source, yours to keep</li>
            <li><CyIcon name="retry" size={13} /> Fixes its own errors</li>
            <li><CyIcon name="shield" size={13} /> Safety-checked</li>
            <li><CyIcon name="layers" size={13} /> Every change is a new version</li>
          </ul>
        </div>
      </section>

      {running.length > 0 && (
        <section className="cy-sec">
          <div className="cy-sec-h"><h2>Weaving now</h2><span className="cy-sub">Builds keep going if you leave. Up to two at once.</span></div>
          <div className="cy-cards">
            {running.map((p) => <ProjectCard key={p.rootId} p={p} onOpen={onOpen} />)}
          </div>
        </section>
      )}

      <section className="cy-sec">
        <div className="cy-sec-h">
          <h2>Start from a template</h2>
          <div className="cy-cats" role="tablist">
            {CYRUS_TEMPLATE_CATS.map((c) => <button key={c} type="button" role="tab" aria-selected={cat === c} className={`cy-cat ${cat === c ? "on" : ""}`} onClick={() => setCat(c)}>{c}</button>)}
          </div>
        </div>
        <div className="cy-tpls">
          {tpl.map((t) => {
            const e = estimate(t.prompt, t.model);
            const m = cyrusModel(t.model);
            return (
              <button key={t.id} type="button" className="cy-tpl" onClick={() => { composerRef.current?.setText(t.prompt, t.model); window.scrollTo({ top: 0, behavior: "smooth" }); }}>
                <span className="cy-tpl-top">
                  <Glyph id={`tpl-${t.id}`} size={30} />
                  <span className="cy-tpl-cat">{t.cat}</span>
                </span>
                <b className="cy-tpl-t">{t.title}</b>
                <span className="cy-tpl-d">{t.blurb}</span>
                <span className="cy-tpl-f">
                  <span className="cy-model-dot" style={{ background: m.hue }} /> {m.name}
                  <span className="cy-tpl-sep">·</span> ~{e.minutes[0]}–{e.minutes[1]} min
                  <span className="cy-tpl-use">Use <CyIcon name="chevr" size={12} /></span>
                </span>
              </button>
            );
          })}
        </div>
      </section>

      {projects.filter((p) => !p.running).length > 0 && (
        <section className="cy-sec cy-recent">
          <div className="cy-sec-h"><h2>Your mods</h2><span className="cy-sub">{projects.length} project{projects.length === 1 ? "" : "s"} · press P to jump to one</span></div>
          <div className="cy-cards">
            {projects.filter((p) => !p.running).slice(0, 9).map((p) => <ProjectCard key={p.rootId} p={p} onOpen={onOpen} />)}
          </div>
        </section>
      )}
      <p className="cy-legal">Cyrus builds Paper server plugins (Java). Not an official Minecraft product. Not approved by or associated with Mojang or Microsoft.</p>
    </div>
  );
}

function ProjectCard({ p, onOpen }: { p: CyrusProject; onOpen: (p: CyrusProject) => void }) {
  const r = p.running;
  const b = r ?? p.head ?? p.latest;
  const s = p.head?.result?.summary?.tagline;
  return (
    <button type="button" className={`cy-pc ${r ? "run" : ""}`} onClick={() => onOpen(p)}>
      <span className="cy-pc-top">
        <Glyph id={p.rootId} size={40} state={r ? "running" : p.head ? "ok" : "bad"} progress={r ? PROGRESS[r.status] : undefined} />
        <span className="flex min-w-0 flex-1 flex-col">
          <b className="cy-pc-t">{p.title}</b>
          <span className={`cy-ri-s st-${b.status}`}>{r ? <><i className="cy-dot st-run" />{CYRUS_STATUS_LABEL[r.status]}</> : <>v{versionNumber(p, b.id)} · {CYRUS_STATUS_LABEL[b.status]}</>}</span>
        </span>
        {p.meta.favourite && <CyIcon name="star" size={13} fill className="cy-amber" />}
      </span>
      <span className="cy-pc-d">{s || p.latest.changeRequest || p.latest.prompt}</span>
      {r && <span className="cy-pc-bar"><i style={{ width: `${Math.round((PROGRESS[r.status] ?? 0.1) * 100)}%` }} /></span>}
      {!r && p.head && <span className="cy-badge sm"><CyIcon name="sparkle" size={9} /> Cyrus</span>}
    </button>
  );
}

