.cy-vnode.st-failed .core { fill: var(--cy-sky); stroke: var(--cy-bad); stroke-width: 1.5; filter: none; }
.cy-vnode.run .core { fill: var(--cy-n3); animation: cy-blink 1.2s ease-in-out infinite; }
.cy-vnode .ring { fill: none; stroke: var(--cy-n1); stroke-width: 1.2; stroke-dasharray: 3 3; animation: cy-spin-slow 9s linear infinite; transform-origin: center; transform-box: fill-box; }
