  .cy-diff-body .cy-view-scroll { max-height: 480px; }
  .cy-cmp-pick { margin-left: 0; }
  .cy-dock { bottom: calc(80px + env(safe-area-inset-bottom)); }
  .cy-dock::before { left: -12px; right: -12px; }
  .cy-tab { padding: 0 11px; font-size: 13px; }
  .cy-tab-k { display: none; }
  .cy-cats { margin-left: 0; width: 100%; }
  .cy-tpls { grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 10px; }
