@keyframes cy-pop { from { opacity: 0; transform: scale(.6); } }
@keyframes cy-toast { from { opacity: 0; transform: translateY(14px) scale(.96); } }
@keyframes cy-file-in { from { opacity: 0; transform: translateX(-8px); background: rgba(62, 240, 208, .18); } }
