  .cy-root *, .cy-root *::before, .cy-root *::after { animation-duration: .001s !important; animation-iteration-count: 1 !important; transition-duration: .001s !important; }
  .cy-root .cy-spin { animation: cy-spin 1.6s linear infinite !important; }
}

