// LOCAL MOCK of the Mod Builder build service, for Cyrus UI screenshots only.
// Serves REAL build records + sources fetched read-only from the service (fx/),
// and simulates new builds by replaying a real fixture's files as live events.
// Control: POST /_set {id, status, ...} freezes a build at a stage.
"use strict";
const http = require("http");
const fs = require("fs");
const path = require("path");
const FX = path.join(__dirname, "fx");
const PORT = 7399;
const now = () => new Date().toISOString();
const ago = (s) => new Date(Date.now() - s * 1000).toISOString();

const fixtures = {};
for (const f of fs.readdirSync(FX)) if (f.endsWith(".json")) { const d = JSON.parse(fs.readFileSync(path.join(FX, f))); fixtures[d.id] = d; }
const recs = new Map(); // id -> { rec, fx, sim }

function fixtureFor(prompt, changeRequest) {
  const p = (prompt + " " + (changeRequest || "")).toLowerCase();
  if (changeRequest && /heal|feed/.test(p)) return "p0-heal01c1";
  if (changeRequest && /streak|daily/.test(p)) return "mb16f8378db9c3e2b68cbe";
  if (/econom|coin|shop/.test(p)) return "p0-econ01";
  if (/scoreboard|sidebar|stats/.test(p)) return "p0-score01";
  if (/spleef/.test(p)) return "p0-spleef01";
  if (/zone|grief/.test(p)) return "p0-zones01";
  if (/boss/.test(p)) return "mb900780697eb88bcaaede";
  if (/streak|daily/.test(p)) return "mb67f7a97b866da50800f4";
  if (/join|welcome/.test(p)) return "p0-joinmsg01";
  return "p0-heal01";
}

// A frozen or progressing in-flight record built from a fixture.
function simRecord(id, body, fxId, stage, startedSecAgo = 60) {
  const fx = fixtures[fxId];
  const names = fx.files.filter((f) => f.path.startsWith("src/")).map((f) => f.path.split("/").pop());
  const order = ["queued", "planning", "coding", "compiling", "repairing", "scanning"];
  const si = order.indexOf(stage);
  const ev = [{ at: ago(startedSecAgo + 4), stage: "queued", message: "Waiting for a free builder" }];
  let t = startedSecAgo;
  const push = (stage, message) => { ev.push({ at: ago(Math.max(0, t)), stage, message }); t -= 4; };
  if (si >= 1) { push("planning", body.baseBuildId ? "Reading your existing plugin and planning the change" : "Planning the plugin from your description"); push("planning", "Reading build.gradle.kts"); }
  if (si >= 2) { push("coding", "Writing the plugin code"); const k = si === 2 ? Math.max(2, Math.ceil(names.length * 0.6)) : names.length; for (const n of names.slice(0, k)) push("coding", `${body.baseBuildId ? "Edited" : "Wrote"} ${n}`); }
  if (si >= 3) push("compiling", `Compiling against Paper ${body.mcVersion}`);
  if (si >= 4 && stage === "repairing") { push("repairing", "2 compile errors found. Fixing it automatically (fix 1 of 3)"); push("repairing", `Edited ${names.find((n) => n.endsWith(".java"))}`); }
  if (si >= 5) push("scanning", "Scanning the compiled plugin for risky behaviour");
  return {
    id, status: stage, prompt: body.prompt, changeRequest: body.changeRequest || null, baseBuildId: body.baseBuildId || null, mcVersion: body.mcVersion,
    error: null, errorCode: null, attempts: stage === "repairing" ? 2 : 1, repairs: stage === "repairing" ? 1 : 0, costUsd: 0.1, durationMs: 0, pluginName: null,
    jar: null, summary: null, commands: [], permissions: [], config: [], warnings: [], files: [], safety: null, events: ev,
    queuePosition: stage === "queued" ? 1 : 0, finishedAt: null,
  };
}

function finished(id, body, fxId, secs) {
  const fx = fixtures[fxId];
  return { ...fx, id, prompt: body.prompt, changeRequest: body.changeRequest || null, baseBuildId: body.baseBuildId || null, mcVersion: body.mcVersion, durationMs: secs * 1000, finishedAt: now(), queuePosition: 0 };
}

// Live simulation: advance by wall clock.
function tick(e) {
  if (!e.sim) return;
  const s = (Date.now() - e.sim.t0) / 1000;
  const { body, fxId } = e.sim;
  const plan = [[0, "queued"], [2, "planning"], [7, "coding"], [7 + e.sim.n * 2.2, "compiling"], [11 + e.sim.n * 2.2, "scanning"], [15 + e.sim.n * 2.2, "succeeded"]];
  let st = "queued";
  for (const [at, k] of plan) if (s >= at) st = k;
  if (st === "succeeded") { e.rec = finished(e.rec.id, body, fxId, Math.round(s)); e.sim = null; return; }
  const r = simRecord(e.rec.id, body, fxId, st, Math.round(s));
  if (st === "coding") {
    const k = Math.max(1, Math.floor((s - 7) / 2.2) + 1);
    const names = fixtures[fxId].files.filter((f) => f.path.startsWith("src/")).map((f) => f.path.split("/").pop());
    r.events = r.events.filter((x) => !/^(Wrote|Edited) /.test(x.message));
    names.slice(0, k).forEach((n, i) => r.events.push({ at: new Date(e.sim.t0 + (7 + i * 2.2) * 1000).toISOString(), stage: "coding", message: `${body.baseBuildId ? "Edited" : "Wrote"} ${n}` }));
  }
  e.rec = r;
}

function get(id) {
  if (recs.has(id)) { const e = recs.get(id); tick(e); return e; }
  if (fixtures[id]) { const e = { rec: fixtures[id], fx: id }; recs.set(id, e); return e; }
  return null;
}

const send = (res, code, body) => { res.writeHead(code, { "Content-Type": "application/json" }); res.end(JSON.stringify(body)); };
const readBody = (req) => new Promise((r) => { let b = ""; req.on("data", (d) => (b += d)); req.on("end", () => { try { r(JSON.parse(b || "{}")); } catch { r({}); } }); });

http.createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  const parts = url.pathname.split("/").filter(Boolean);
  if (url.pathname === "/health") return send(res, 200, { ok: true, service: "mock" });
  if (req.method === "POST" && url.pathname === "/_set") {
    const b = await readBody(req);
    // {id, prompt, mcVersion, fx, status, ago, baseBuildId, changeRequest}
    const fxId = b.fx || fixtureFor(b.prompt || "", b.changeRequest);
    const e = { rec: b.status === "succeeded" ? finished(b.id, b, fxId, 90) : b.status === "failed" ? { ...fixtures[b.fx], id: b.id } : simRecord(b.id, b, fxId, b.status, b.ago || 60), fx: fxId };
    recs.set(b.id, e);
    return send(res, 200, { ok: true, status: e.rec.status, fx: fxId });
  }
  if (req.method === "POST" && url.pathname === "/builds") {
    const b = await readBody(req);
    const fxId = fixtureFor(b.prompt, b.changeRequest);
    const n = fixtures[fxId].files.filter((f) => f.path.startsWith("src/")).length;
    const e = { rec: simRecord(b.id, b, fxId, "queued", 0), fx: fxId, sim: { t0: Date.now(), body: b, fxId, n } };
    recs.set(b.id, e);
    console.log("create", b.id, fxId, JSON.stringify({ tier: b.tier, modelHint: b.modelHint }));
    return send(res, 202, e.rec);
  }
  if (parts[0] === "builds" && parts[1]) {
    const e = get(parts[1]);
    if (!e) return send(res, 404, { error: "not found" });
    if (req.method === "GET" && parts.length === 2) return send(res, 200, e.rec);
    if (req.method === "POST" && parts[2] === "cancel") { e.sim = null; e.rec = { ...e.rec, status: "failed", errorCode: "cancelled", error: "Build cancelled.", finishedAt: now() }; return send(res, 200, { ok: true }); }
    if (parts[2] === "artifact") {
      const f = path.join(FX, `${e.fx}.jar.bin`);
      if (!fs.existsSync(f)) return send(res, 404, {});
      return res.end(fs.readFileSync(f));
    }
    if (parts[2] === "source") {
      if (e.rec.status !== "succeeded" && e.rec.status !== "failed") return send(res, 404, { error: "no such file" });
      const p = String(url.searchParams.get("path") || "");
      const f = path.join(FX, "src", e.fx, p);
      if (!f.startsWith(path.join(FX, "src", e.fx)) || !fs.existsSync(f)) return send(res, 404, { error: "no such file" });
      res.writeHead(200, { "Content-Type": "text/plain; charset=utf-8" });
      return res.end(fs.readFileSync(f));
    }
  }
  send(res, 404, { error: "nope" });
}).listen(PORT, "127.0.0.1", () => console.log("mock modbuilder on", PORT, Object.keys(fixtures).length, "fixtures"));

