// THROWAWAY seed for nxeon_agt_cyrus (Cyrus UI verification). Never run against prod.
// Rows mirror REAL builds fetched read-only from the build service (served by the local mock),
// so the portal's own sync pulls real results, jars and source.
import { createHash } from "node:crypto";
import { writeFileSync } from "node:fs";
import { SignJWT } from "jose";
import { PrismaClient } from "@prisma/client";
const db = new PrismaClient();
const MOCK = "http://127.0.0.1:7399";

async function session(userId: string) {
  const token = await new SignJWT({ sub: userId, sv: 0, typ: "session" }).setProtectedHeader({ alg: "HS256" }).setIssuedAt().setExpirationTime("2d").sign(new TextEncoder().encode(process.env.AUTH_SECRET!));
  await db.userSession.create({ data: { userId, tokenHash: createHash("sha256").update(token).digest("hex") } });
  return token;
}
const mock = (b: Record<string, unknown>) => fetch(MOCK + "/_set", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify(b) }).then((r) => r.json());

async function main() {
  if (!/nxeon_agt_cyrus/.test(process.env.DATABASE_URL ?? "")) throw new Error("refusing: not the throwaway DB");
  const scene = process.argv[2] || "full";
  const mkUser = async (email: string, name: string) => {
    await db.user.deleteMany({ where: { email } });
    return db.user.create({ data: { email, passwordHash: "x", name, emailVerifiedAt: new Date(), heardAboutUs: "other", balanceCents: 2500 } as never });
  };
  await db.modBuild.deleteMany({});
  await db.server.deleteMany({ where: { hostname: { startsWith: "agt-cy-" } } });
  const owner = await mkUser("nicholas.sj.albanese@gmail.com", "Nicholas Albanese");
  const other = await mkUser("someone-else@example.test", "Other Customer");
  const plan = await db.plan.upsert({ where: { slug: "agt-base" }, update: {}, create: { slug: "agt-base", name: "Base", cpuCores: 2, ramMB: 4096, diskGB: 30, priceCents: 500 } });
  const tpl = await db.osTemplate.upsert({ where: { slug: "agt-minecraft" }, update: {}, create: { slug: "agt-minecraft", name: "Minecraft", category: "APPLICATION", family: "minecraft", vmid: 9000, setupScript: "docker run -d --name mc itzg/minecraft-server" } as never });
  const gp = await db.gamePlan.upsert({ where: { id: "agt-gp4" }, update: {}, create: { id: "agt-gp4", name: "Minecraft 4 GB", gameFamily: "minecraft", ramMB: 4096, cpuCores: 2, diskGB: 30, slots: 20, priceCents: 1294, basePlanId: plan.id } as never });
  const mk = (hostname: string, label: string, variant: string, status: string, ip: string) =>
    db.server.create({ data: { name: hostname, label, hostname, userId: owner.id, planId: plan.id, osTemplateId: tpl.id, gamePlanId: gp.id, status, gameVariant: variant, gameConfig: { VERSION: "1.21.11" }, ipAddress: ip } as never });
  await mk("agt-cy-survival", "Survival SMP", "paper", "RUNNING", "10.99.1.5");
  await mk("agt-cy-creative", "Creative build", "purpur", "STOPPED", "10.99.1.6");
  await mk("agt-cy-modded", "Modded pack", "fabric", "RUNNING", "10.99.1.7");

  const min = (m: number) => new Date(Date.now() - m * 60_000);
