mkdir -p /root/agent-notes/cyrus && cat > /root/agent-notes/cyrus/shot.mjs <<'EOF'
// usage: node shot.mjs <name> <path>   env: VIEWS=desktop,mobile THEMES=dark,light ACT='async (page)=>{}' FULL=1 WAIT=ms TOK=ownerTok
// Writes /root/agent-notes/cyrus/<ROUND>/<name>-<view>[-light].png
import { createRequire } from "node:module";
import { readFileSync, mkdirSync } from "node:fs";
const require = createRequire("/opt/nxeon/node_modules/");
const { chromium } = require("playwright");
const [, , name, path] = process.argv;
const tok = JSON.parse(readFileSync(process.env.TOKENS, "utf8"));
const BASE = process.env.BASE ?? "http://localhost:3149";
const OUT = `/root/agent-notes/cyrus/${process.env.ROUND ?? "r1"}`;
mkdirSync(OUT, { recursive: true });
const VIEWS = (process.env.VIEWS ?? "desktop,mobile").split(",");
const THEMES = (process.env.THEMES ?? "dark").split(",");
const browser = await chromium.launch({ args: ["--disable-gpu", "--use-fake-ui-for-media-stream", "--use-fake-device-for-media-stream"] });
const views = { desktop: { width: 1440, height: 1000, mobile: false }, mobile: { width: 390, height: 844, mobile: true } };
for (const vt of VIEWS) for (const theme of THEMES) {
  const v = views[vt];
  const ctx = await browser.newContext({ viewport: { width: v.width, height: v.height }, deviceScaleFactor: 1, isMobile: v.mobile, hasTouch: v.mobile, colorScheme: theme, reducedMotion: process.env.RM ?? "no-preference", permissions: ["microphone", "clipboard-read", "clipboard-write"] });
  await ctx.addCookies([{ name: tok.cookie, value: tok[process.env.TOK ?? "ownerTok"], url: BASE }, { name: "nxeon_cookie_consent", value: "all", url: BASE }]);
  const page = await ctx.newPage();
  await page.addInitScript((t) => { try { localStorage.setItem("nx-theme", t); localStorage.setItem("nx-tour-dismissed", "1"); } catch {} }, theme);
  const errs = [];
  page.on("pageerror", (e) => errs.push(String(e)));
  page.on("console", (m) => { if (m.type() === "error") errs.push("console: " + m.text().slice(0, 200)); });
  await page.goto(BASE + path, { waitUntil: "networkidle", timeout: 240000 }).catch((e) => errs.push("goto " + e));
  for (const label of ["Got it", "Skip", "Not now", "Skip tour", "Maybe later"]) {
    const b = page.getByRole("button", { name: label, exact: true });
    if (await b.count().catch(() => 0)) await b.first().click({ timeout: 1000 }).catch(() => {});
  }
  if (process.env.ACT) { try { await eval(process.env.ACT)(page, vt); } catch (e) { errs.push("act " + e); } }
  await page.waitForTimeout(Number(process.env.WAIT ?? 2500));
  const overflow = await page.evaluate(() => document.documentElement.scrollWidth - window.innerWidth).catch(() => 0);
  const file = `${OUT}/${name}-${vt}${theme === "light" ? "-light" : ""}.png`;
  await page.screenshot({ path: file, fullPage: process.env.FULL !== "0" });
  console.log(file, overflow > 1 ? `OVERFLOW ${overflow}px` : "", errs.length ? "ERR " + errs.join(" | ").slice(0, 600) : "");
  await ctx.close();
}
await browser.close();
EOF
cd /root/agent-notes/cyrus && TOKENS=/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/tokens.json VIEWS=desktop FULL=0 timeout 400 node shot.mjs home /dashboard/cyrus 2>&1 | tail -5

