11	export function Glyph({ id, size = 36, state = "idle", progress }: { id: string; size?: number; state?: "idle" | "running" | "ok" | "bad"; progress?: number }) {
12	  const g = useMemo(() => {
13	    let h = hashSeed(id);
14	    const r = () => { h ^= h << 13; h ^= h >>> 17; h ^= h << 5; return ((h >>> 0) % 1000) / 1000; };
15	    const n = 5 + Math.floor(r() * 3);
16	    const pts = Array.from({ length: n }, (_, i) => {
17	      const a = (i / n) * Math.PI * 2 + r() * 0.9;
18	      const d = 5 + r() * 9;
19	      // Rounded: server and client Math.cos can differ in the last digit (hydration).
20	      return { x: Math.round((18 + Math.cos(a) * d) * 100) / 100, y: Math.round((18 + Math.sin(a) * d) * 100) / 100, s: Math.round((0.9 + r() * 1.3) * 100) / 100 };
21	    });
22	    const edges: [number, number][] = [];
23	    for (let i = 0; i < n; i++) {
24	      let best = -1, bd = Infinity;
25	      for (let j = 0; j < n; j++) {
26	        if (j === i) continue;
27	        const d = (pts[i].x - pts[j].x) ** 2 + (pts[i].y - pts[j].y) ** 2;
28	        if (d < bd && !edges.some(([a, b]) => (a === j && b === i))) { bd = d; best = j; }

