import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { readFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";
import { diffLines, diffStats, hunks, sideBySide, fileChanges } from "../lib/cyrus/diff";
import { estimate, modelAdvice } from "../lib/cyrus/estimate";
import { applyProjectPatch, parseProjectPatch, readCyrusMeta } from "../lib/cyrus/meta";
import { CYRUS_MODEL_ROUTE, isCyrusModel } from "../lib/cyrus/models";
import { draftTitle, groupProjects, spaced, versionNumber } from "../lib/cyrus/projects";
import type { ModBuildView } from "../lib/modbuilder/types";

describe("cyrus diff", () => {
  it("finds a changed line with context", () => {
    const ops = diffLines("a\nb\nc\nd\n", "a\nB\nc\nd\ne\n");
    assert.deepEqual(diffStats(ops), { added: 2, removed: 1 });
    assert.deepEqual(ops.filter((o) => o.t !== "eq").map((o) => `${o.t}:${o.text}`), ["del:b", "add:B", "add:e"]);
    const rows = sideBySide(ops);
    assert.equal(rows.find((r) => r.left?.text === "b")?.right?.text, "B");
  });
  it("identical files have no changes; empty -> content is all adds", () => {
    assert.deepEqual(diffStats(diffLines("x\ny", "x\ny")), { added: 0, removed: 0 });
    assert.deepEqual(diffStats(diffLines("", "1\n2\n3")), { added: 3, removed: 0 });
  });
  it("matches a brute-force LCS on random inputs", () => {
    let seed = 7;
    const r = () => ((seed = (seed * 1103515245 + 12345) & 0x7fffffff) % 4);
    for (let k = 0; k < 200; k++) {
      const a = Array.from({ length: r() * 3 + 1 }, () => "abcd"[r()]);
      const b = Array.from({ length: r() * 3 + 1 }, () => "abcd"[r()]);
      const ops = diffLines(a.join("\n"), b.join("\n"));
      // replaying ops reconstructs both sides
      assert.deepEqual(ops.filter((o) => o.t !== "add").map((o) => o.text), a);
      assert.deepEqual(ops.filter((o) => o.t !== "del").map((o) => o.text), b);
      // minimal: equal lines == LCS length
      const dp = Array.from({ length: a.length + 1 }, () => new Array(b.length + 1).fill(0));
      for (let i = 1; i <= a.length; i++) for (let j = 1; j <= b.length; j++) dp[i][j] = a[i - 1] === b[j - 1] ? dp[i - 1][j - 1] + 1 : Math.max(dp[i - 1][j], dp[i][j - 1]);
      assert.equal(ops.filter((o) => o.t === "eq").length, dp[a.length][b.length]);
    }
  });
  it("collapses long unchanged runs into hunks", () => {
    const a = Array.from({ length: 50 }, (_, i) => `l${i}`);
    const b = [...a]; b[25] = "changed";
    const hs = hunks(diffLines(a.join("\n"), b.join("\n")), 3);
    assert.equal(hs.length, 1);
    assert.equal(hs[0].skippedBefore, 22);
  });
  it("classifies files by presence", () => {
    const c = fileChanges([{ path: "a", size: 1 }, { path: "b", size: 2 }], [{ path: "b", size: 3 }, { path: "c", size: 1 }]);
    assert.deepEqual(c.map((x) => `${x.path}:${x.kind}`), ["a:removed", "b:changed", "c:added"]);
  });
});

describe("cyrus estimate", () => {
  it("routes simple, standard and complex requests", () => {
    assert.equal(estimate("A /heal command that heals the player.", "saka").complexity, "simple");
    assert.equal(estimate("A coin economy: /balance, /pay, a /shop chest menu with prices in the config, saved to disk.", "saka").complexity, "standard");
    const big = estimate("A boss fight with phases and minions, a quest system with daily quests in a menu, a leaderboard scoreboard, teams, a lobby and rounds, rewards saved to disk.", "katara");
    assert.equal(big.complexity, "complex");
    assert.equal(big.recommended, "yakko");
    assert.equal(modelAdvice(big, "katara"), "under");
  });
  it("costs scale with the model", () => {
    const t = "A coin economy with a /shop menu saved to disk.";
    assert.ok(estimate(t, "katara").usd[1] < estimate(t, "saka").usd[1]);
    assert.ok(estimate(t, "saka").usd[1] < estimate(t, "yakko").usd[1]);
  });
});

describe("cyrus meta + models", () => {
  it("reads only clean fields", () => {
    assert.deepEqual(readCyrusMeta({ model: "yakko", favourite: true, title: "  Hi ", headBuildId: "bad id!", attachments: [{ n: 1, name: "x.png", type: "image/png", size: 3 }, { n: 2, type: "text/html" }] }),
      { model: "yakko", favourite: true, title: "Hi", attachments: [{ n: 1, name: "x.png", type: "image/png", size: 3 }] });
    assert.deepEqual(readCyrusMeta("nope"), {});
  });
  it("validates project patches", () => {
    assert.equal(parseProjectPatch({ headBuildId: "other" }, ["a"]).ok, false);
    assert.equal(parseProjectPatch({}, ["a"]).ok, false);
    const p = parseProjectPatch({ headBuildId: "a", favourite: true, title: "" }, ["a"]);
    assert.ok(p.ok);
    if (p.ok) assert.deepEqual(applyProjectPatch({ title: "Old", model: "saka" }, p.patch), { model: "saka", headBuildId: "a", favourite: true });
  });
  it("maps every model to a service tier", () => {
    assert.ok(isCyrusModel("katara") && !isCyrusModel("opus"));
    assert.deepEqual(CYRUS_MODEL_ROUTE.yakko, { tier: "complex", modelHint: "opus" });
  });
});

const view = (id: string, extra: Partial<ModBuildView> = {}): ModBuildView => ({
  id, status: "succeeded", prompt: "A heal command for players.", changeRequest: null, baseBuildId: null, rootBuildId: id, mcVersion: "1.21.11", pluginName: "HealPlus", version: "1.0.0",
  error: null, errorCode: null, attempts: 1, durationMs: 1000, jarName: null, jarSize: null, createdAt: "2026-10-07T00:00:00.000Z", finishedAt: null, result: null, lastInstall: null, ...extra,
});

describe("cyrus projects", () => {
  it("groups by root, picks head and running build", () => {
    const ps = groupProjects([
      view("r1"),
      view("r1c1", { rootBuildId: "r1", baseBuildId: "r1", createdAt: "2026-10-07T01:00:00.000Z" }),
      view("r1c2", { rootBuildId: "r1", baseBuildId: "r1c1", status: "coding", createdAt: "2026-10-07T02:00:00.000Z" }),
      view("r2", { pluginName: null, prompt: "A spleef mini-game with rounds", status: "failed", createdAt: "2026-10-06T00:00:00.000Z" }),
    ]);
    assert.equal(ps.length, 2);
    assert.equal(ps[0].rootId, "r1"); // running first
    assert.equal(ps[0].head?.id, "r1c1");
    assert.equal(ps[0].running?.id, "r1c2");
    assert.equal(versionNumber(ps[0], "r1c2"), 3);
    assert.equal(ps[0].title, "Heal Plus");
    assert.equal(ps[1].head, null);
    assert.equal(ps[1].title, "Spleef mini-game with rounds");
  });
  it("honours a restored head", () => {
    const [p] = groupProjects([view("r1", { cyrus: { headBuildId: "r1" } }), view("r1c1", { rootBuildId: "r1", createdAt: "2026-10-07T01:00:00.000Z" })]);
    assert.equal(p.head?.id, "r1");
  });
  it("titles", () => {
    assert.equal(spaced("DailyRewards"), "Daily Rewards");
    assert.equal(draftTitle("Make a coin shop: players earn coins"), "Coin shop");
  });
});

function files(dir: string): string[] {
  return readdirSync(dir).flatMap((n) => { const p = join(dir, n); return statSync(p).isDirectory() ? files(p) : [p]; });
}
describe("cyrus is behind the mod builder preview gate", () => {
  it("both pages render through the gated loader", () => {
    for (const f of files("app/dashboard/cyrus").filter((f) => f.endsWith("page.tsx"))) assert.match(readFileSync(f, "utf8"), /CyrusPage\(/, f);
    assert.match(readFileSync("app/dashboard/cyrus/shared.tsx", "utf8"), /await requireModBuilderUser\(\)/);
  });
  it("the static nav never lists it", () => {
    assert.doesNotMatch(readFileSync("lib/nx/nav.ts", "utf8"), /cyrus/i);
  });
  it("new API routes resolve the preview user", () => {
    for (const f of ["app/api/mod-builder/uploads/route.ts", "app/api/mod-builder/projects/[id]/route.ts", "app/api/mod-builder/builds/[id]/attachments/[n]/route.ts"]) {
      assert.match(readFileSync(f, "utf8"), /ownedBuild\(|modBuilderUser\(\)/, f);
    }
  });
  it("customer copy never names the underlying models", () => {
    for (const f of files("components/cyrus")) assert.doesNotMatch(readFileSync(f, "utf8"), /\b(Haiku|Sonnet|Opus|Claude|Anthropic)\b/, f);
  });
});

